INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$9421ed62$SATQ$, $SATQ$bc6ee0b9-9725-4ac6-8dde-b98186c5dfb4$SATQ$::uuid, $SATQ$c725315b-5043-4999-8300-3e04d89a924c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In 2007, computer scientist Luis von Ahn was working on converting printed books into a digital format. He found that some words were distorted enough that digital scanners couldn&rsquo;t recognize them, but most humans could easily read them. Based on that finding, von Ahn invented a simple security test to keep automated &ldquo;bots&rdquo; out of websites. The first version of the reCAPTCHA test asked users to type one known word and one of the many words scanners couldn&rsquo;t recognize. Correct answers proved the users were humans and added data to the book-digitizing project.</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"8f07e0aa-e0bf-49b6-966b-8cc064bd8e34","content":"<p>To discuss von Ahn&rsquo;s invention of reCAPTCHA</p>"},{"id":"512d7a53-695b-48aa-8b54-a29170dd65af","content":"<p>To explain how digital scanners work</p>"},{"id":"792e9285-1c79-4819-a6c7-f871ab31c6a1","content":"<p>To call attention to von Ahn&rsquo;s book-digitizing project</p>"},{"id":"1a5c0681-3e32-46e8-b30b-dc1f3320c8d2","content":"<p>To indicate how popular reCAPTCHA is</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["8f07e0aa-e0bf-49b6-966b-8cc064bd8e34"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately states the main purpose of the text. After providing a brief introduction to computer scientist Luis von Ahn, the text focuses on discussing how von Ahn&rsquo;s digitization work led to the invention of a digital security test known as reCAPTCHA. </p><p>Choice B is incorrect because the text doesn&rsquo;t address how digital scanners work. Choice C is incorrect. Although the text mentions von Ahn&rsquo;s book-digitizing project, that information is provided as a detail, not as the main purpose of the text. Choice D is incorrect because the text doesn&rsquo;t provide any indication of reCAPTCHA&rsquo;s popularity; instead, it describes reCAPTCHA&rsquo;s origin. </p>$SATQ$, false, 0, $SATQ$OSP-010-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$ad96eefe-ebe6-4181-8352-9450a2614dbe$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9421ed62","external_id":"bc6ee0b9-9725-4ac6-8dde-b98186c5dfb4","vaultid":"c725315b-5043-4999-8300-3e04d89a924c","uId":"3e625130-1460-4d6b-9e10-881fc3de26f3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In 2007, computer scientist Luis von Ahn was working on converting printed books into a digital format. He found that some words were distorted enough that digital scanners couldn&rsquo;t recognize them, but most humans could easily read them. Based on that finding, von Ahn invented a simple security test to keep automated &ldquo;bots&rdquo; out of websites. The first version of the reCAPTCHA test asked users to type one known word and one of the many words scanners couldn&rsquo;t recognize. Correct answers proved the users were humans and added data to the book-digitizing project.</p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"8f07e0aa-e0bf-49b6-966b-8cc064bd8e34","content":"<p>To discuss von Ahn&rsquo;s invention of reCAPTCHA</p>"},{"id":"512d7a53-695b-48aa-8b54-a29170dd65af","content":"<p>To explain how digital scanners work</p>"},{"id":"792e9285-1c79-4819-a6c7-f871ab31c6a1","content":"<p>To call attention to von Ahn&rsquo;s book-digitizing project</p>"},{"id":"1a5c0681-3e32-46e8-b30b-dc1f3320c8d2","content":"<p>To indicate how popular reCAPTCHA is</p>"}],"keys":["8f07e0aa-e0bf-49b6-966b-8cc064bd8e34"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately states the main purpose of the text. After providing a brief introduction to computer scientist Luis von Ahn, the text focuses on discussing how von Ahn&rsquo;s digitization work led to the invention of a digital security test known as reCAPTCHA. </p><p>Choice B is incorrect because the text doesn&rsquo;t address how digital scanners work. Choice C is incorrect. Although the text mentions von Ahn&rsquo;s book-digitizing project, that information is provided as a detail, not as the main purpose of the text. Choice D is incorrect because the text doesn&rsquo;t provide any indication of reCAPTCHA&rsquo;s popularity; instead, it describes reCAPTCHA&rsquo;s origin. </p>","parenttemplatename":"OSP-010-TSP","parenttemplateid":"","templateclusterid":"ad96eefe-ebe6-4181-8352-9450a2614dbe","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959314,"updateDate":1691007959314}$SATQ$::jsonb, 1691007959314, 1691007959314),
    ($SATQ$94eb800d$SATQ$, $SATQ$81858a15-8a22-46d2-a60d-5e7fffdeda11$SATQ$::uuid, $SATQ$0109c6bd-2a12-4d9d-829c-a18bf38b7b3c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>For a 2020 exhibition, photographer and neurobiologist Okunola Jeyifous <span aria-hidden="true">______</span><span class="sr-only">blank</span> a series of new images based on a series of alphabet posters from the 1970s known as the &ldquo;Black ABCs,&rdquo; which featured Black children from Chicago. Jeyifous photographed the now-adult models and layered the photos over magnified images of the models&rsquo; cells, resulting in what he called &ldquo;micro and macro portraiture.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"ae5955bd-22d5-4653-9d03-b10d04f2b460","content":"<p>validated</p>"},{"id":"c7118b73-a4c6-4a3c-8d04-86304fb9f3ca","content":"<p><strong> </strong>created</p>"},{"id":"6a1da608-1b02-4b79-b8af-7a036339bfc5","content":"<p>challenged</p>"},{"id":"fbbfe9ef-a4d9-4763-95a6-dfa577ed84aa","content":"<p>restored</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["c7118b73-a4c6-4a3c-8d04-86304fb9f3ca"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically and precisely completes the text&rsquo;s discussion of Jeyifous&rsquo;s series of images for the 2020 exhibition. In this context, &ldquo;created&rdquo; means produced. The text explains that Jeyifous, a photographer and neurobiologist, photographed adults who had appeared as children in posters from the 1970s, then combined those photographs with magnified images of the adults&rsquo; cells&mdash;a process that resulted in what he called &ldquo;micro and macro portraiture.&rdquo; This context suggests that Jeyifous drew on his dual interests in photography and neurobiology to produce the images for display in the exhibition. </p><p>Choice A is incorrect because there&rsquo;s nothing in the text to suggest that Jeyifous &ldquo;validated,&rdquo; or corroborated, the series of images. The text describes Jeyifous&rsquo;s process for composing the images but&nbsp;doesn&rsquo;t describe Jeyifous making an effort to evaluate the images for their artistic or scientific legitimacy. Choice C is incorrect because there&rsquo;s nothing in the text to suggest that Jeyifous &ldquo;challenged,&rdquo; or disputed, an aspect of the images; rather, the focus of the text is on the inspiration behind the images and the method Jeyifous used to achieve them. Choice D is incorrect because the text indicates that Jeyifous made the images himself using a combination of photography and magnified pictures of cells, not that he &ldquo;restored,&rdquo; or reconditioned, the images from a deteriorated state. </p>$SATQ$, false, 0, $SATQ$OSP-902-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$028005c6-8f20-4051-b40a-705b0f5b18a3$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"94eb800d","external_id":"81858a15-8a22-46d2-a60d-5e7fffdeda11","vaultid":"0109c6bd-2a12-4d9d-829c-a18bf38b7b3c","uId":"e1336caf-e58c-44e0-9f90-1acd0148f34e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>For a 2020 exhibition, photographer and neurobiologist Okunola Jeyifous <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a series of new images based on a series of alphabet posters from the 1970s known as the &ldquo;Black ABCs,&rdquo; which featured Black children from Chicago. Jeyifous photographed the now-adult models and layered the photos over magnified images of the models&rsquo; cells, resulting in what he called &ldquo;micro and macro portraiture.&rdquo;</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"ae5955bd-22d5-4653-9d03-b10d04f2b460","content":"<p>validated</p>"},{"id":"c7118b73-a4c6-4a3c-8d04-86304fb9f3ca","content":"<p><strong> </strong>created</p>"},{"id":"6a1da608-1b02-4b79-b8af-7a036339bfc5","content":"<p>challenged</p>"},{"id":"fbbfe9ef-a4d9-4763-95a6-dfa577ed84aa","content":"<p>restored</p>"}],"keys":["c7118b73-a4c6-4a3c-8d04-86304fb9f3ca"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically and precisely completes the text&rsquo;s discussion of Jeyifous&rsquo;s series of images for the 2020 exhibition. In this context, &ldquo;created&rdquo; means produced. The text explains that Jeyifous, a photographer and neurobiologist, photographed adults who had appeared as children in posters from the 1970s, then combined those photographs with magnified images of the adults&rsquo; cells&mdash;a process that resulted in what he called &ldquo;micro and macro portraiture.&rdquo; This context suggests that Jeyifous drew on his dual interests in photography and neurobiology to produce the images for display in the exhibition. </p><p>Choice A is incorrect because there&rsquo;s nothing in the text to suggest that Jeyifous &ldquo;validated,&rdquo; or corroborated, the series of images. The text describes Jeyifous&rsquo;s process for composing the images but&nbsp;doesn&rsquo;t describe Jeyifous making an effort to evaluate the images for their artistic or scientific legitimacy. Choice C is incorrect because there&rsquo;s nothing in the text to suggest that Jeyifous &ldquo;challenged,&rdquo; or disputed, an aspect of the images; rather, the focus of the text is on the inspiration behind the images and the method Jeyifous used to achieve them. Choice D is incorrect because the text indicates that Jeyifous made the images himself using a combination of photography and magnified pictures of cells, not that he &ldquo;restored,&rdquo; or reconditioned, the images from a deteriorated state. </p>","parenttemplatename":"OSP-902-WIC","parenttemplateid":"","templateclusterid":"028005c6-8f20-4051-b40a-705b0f5b18a3","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959354,"updateDate":1691007959354}$SATQ$::jsonb, 1691007959354, 1691007959354),
    ($SATQ$95f037ad$SATQ$, $SATQ$b9466c37-9ae4-46a8-b25f-199f5c56b0db$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>The works of Chicana artist Ester Hernandez are now <span aria-hidden="true">______</span><span class="sr-only">blank</span> in museums both in the United States and abroad, but the murals she contributed to as a member of Las Mujeres Muralistas early in her artistic career were displayed in outdoor public spaces across San Francisco.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"b43ec14e-067e-4b14-a5e4-2b3cab0342a0","content":"<p>invented</p>"},{"id":"59d968a2-4a43-418f-a9bb-0ed9aeaeefa6","content":"<p>adjusted</p>"},{"id":"d64efb0c-8ecb-4e5a-8134-5237dbd5d05e","content":"<p>featured</p>"},{"id":"053c4950-a26c-4a3b-add1-ec2314af3cda","content":"<p>recommended</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["d64efb0c-8ecb-4e5a-8134-5237dbd5d05e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of Ester Hernandez&rsquo;s art. In this context, "featured" means shown prominently. The text focuses on where Hernandez&rsquo;s works have been and continue to be displayed, explaining that her early works, which consisted of murals, could be viewed in outdoor spaces in San Francisco. The central contrast developed in the text is between where her early works could be viewed and where her works can be viewed now, which is in museums across the United States and around the world. The context therefore supports the idea that Hernandez&rsquo;s works are now shown, or featured, in museums globally.</p><p>Choice A is incorrect because in this context "invented" would mean created something for the first time, which isn&rsquo;t supported since the text doesn&rsquo;t discuss where Hernandez creates her works or whether they&rsquo;re original or innovative. Choice B is incorrect because "adjusted" in this context would mean adapted. Although the text mentions that many of Hernandez&rsquo;s early works were outdoor murals and thus it may be reasonable to infer that Hernandez altered her approach to creating art so that her works could be displayed in indoor venues instead, the text makes no mention of how Hernandez&rsquo;s works might have been adapted for such venues. The text focuses on where Hernandez&rsquo;s works have been and continue to be displayed, not on how she or anyone else may have adapted, or adjusted, her works. Choice D is incorrect because "recommended" in this context would mean endorsed or put forth as a suggestion for something that is worth seeing. Although it may be reasonable to say that in choosing to display certain works, museum curators believe such works are worth seeing, the text doesn&rsquo;t discuss the reasons why museums display Hernandez&rsquo;s works. Instead, the text mainly develops a contrast between where Hernandez&rsquo;s early works could once be viewed and where her work can be viewed now.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"95f037ad","external_id":"b9466c37-9ae4-46a8-b25f-199f5c56b0db","vaultid":null,"uId":"0a7a9416-ef6f-4ab1-bf27-c7f41d6fa58e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>The works of Chicana artist Ester Hernandez are now <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in museums both in the United States and abroad, but the murals she contributed to as a member of Las Mujeres Muralistas early in her artistic career were displayed in outdoor public spaces across San Francisco.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"b43ec14e-067e-4b14-a5e4-2b3cab0342a0","content":"<p>invented</p>"},{"id":"59d968a2-4a43-418f-a9bb-0ed9aeaeefa6","content":"<p>adjusted</p>"},{"id":"d64efb0c-8ecb-4e5a-8134-5237dbd5d05e","content":"<p>featured</p>"},{"id":"053c4950-a26c-4a3b-add1-ec2314af3cda","content":"<p>recommended</p>"}],"keys":["d64efb0c-8ecb-4e5a-8134-5237dbd5d05e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of Ester Hernandez&rsquo;s art. In this context, \"featured\" means shown prominently. The text focuses on where Hernandez&rsquo;s works have been and continue to be displayed, explaining that her early works, which consisted of murals, could be viewed in outdoor spaces in San Francisco. The central contrast developed in the text is between where her early works could be viewed and where her works can be viewed now, which is in museums across the United States and around the world. The context therefore supports the idea that Hernandez&rsquo;s works are now shown, or featured, in museums globally.</p><p>Choice A is incorrect because in this context \"invented\" would mean created something for the first time, which isn&rsquo;t supported since the text doesn&rsquo;t discuss where Hernandez creates her works or whether they&rsquo;re original or innovative. Choice B is incorrect because \"adjusted\" in this context would mean adapted. Although the text mentions that many of Hernandez&rsquo;s early works were outdoor murals and thus it may be reasonable to infer that Hernandez altered her approach to creating art so that her works could be displayed in indoor venues instead, the text makes no mention of how Hernandez&rsquo;s works might have been adapted for such venues. The text focuses on where Hernandez&rsquo;s works have been and continue to be displayed, not on how she or anyone else may have adapted, or adjusted, her works. Choice D is incorrect because \"recommended\" in this context would mean endorsed or put forth as a suggestion for something that is worth seeing. Although it may be reasonable to say that in choosing to display certain works, museum curators believe such works are worth seeing, the text doesn&rsquo;t discuss the reasons why museums display Hernandez&rsquo;s works. Instead, the text mainly develops a contrast between where Hernandez&rsquo;s early works could once be viewed and where her work can be viewed now.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323034,"updateDate":1730147323034}$SATQ$::jsonb, 1730147323034, 1730147323034),
    ($SATQ$9645f55e$SATQ$, $SATQ$f13ab5d0-6fea-4c54-999b-ed0ead5c6e92$SATQ$::uuid, $SATQ$de2a8881-0765-4ada-a4e2-988e4f1ee27a$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p><strong><span role="heading" aria-level="2">Text 1</span></strong></p>
<p>For decades, bluegrass musicians have debated whether their genre should exclude influences from mainstream genres such as rock. Many insist that bluegrass is defined by its adherence to the folk music of the US South, out of which bluegrass emerged. Such &ldquo;purists,&rdquo; as they are known, regard the recordings of Bill Monroe, which established the bluegrass sound in the 1940s, as a standard against which the genre should still be measured.</p>
<p>&nbsp;</p>
<p><strong><span role="heading" aria-level="2">Text 2</span></strong></p>
<p>Bluegrass isn&rsquo;t simply an extension of folk traditions into the era of recorded music. In reality, Bill Monroe created the bluegrass sound in the 1940s by combining Southern folk music with commercial genres that had arisen only a few decades before, such as jazz and the blues. Since bluegrass has always been a mixed genre, contemporary bluegrass musicians should not be forbidden from incorporating into it influences from rock and other mainstream genres.</p>$SATQ$, $SATQ$<p>Based on the texts, how would the author of Text 2 most likely regard the perspective of bluegrass purists, as described in Text 1?</p>$SATQ$, $SATQ$[{"id":"1b11c09d-0e00-407f-bf2c-f23ebc79f9da","content":"<p>As inconsistent, since bluegrass purists themselves enjoy other musical genres</p>"},{"id":"6afbe56b-b78d-40d2-8143-34bda6ed3e59","content":"<p>As unrealistic, since bluegrass purists have no way of enforcing their musical preferences</p>"},{"id":"81d17a2b-04a2-4cc9-a587-882616ba7b78","content":"<p>As shortsighted, because bluegrass could enlarge its audience by including influences from mainstream genres</p>"},{"id":"6eff68db-7a5b-4591-bf88-abd682f0a61a","content":"<p>As illogical, because the purists overlook crucial aspects of how the bluegrass sound first originated.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["6eff68db-7a5b-4591-bf88-abd682f0a61a"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. According to Author 1, the &ldquo;purists&rdquo; argue that bluegrass should stick to its folk music roots. But Author 2 points out that this isn&rsquo;t how bluegrass emerged: it actually got its sound from a mix of folk, jazz, and blues. </p><p>Choice A is incorrect. There&rsquo;s nothing in Text 2 about what other genres the purists enjoy, so this inference about Author 2&rsquo;s views isn&rsquo;t supported. Choice B is incorrect. There&rsquo;s nothing in Text 2 about whether or how purists can enforce their preferences, so this inference about Author 2&rsquo;s views isn&rsquo;t supported. Choice C is incorrect. There&rsquo;s nothing in Text 2 about the size of bluegrass&rsquo;s audience, so this inference about Author 2&rsquo;s views isn&rsquo;t supported. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-M001$SATQ$, $SATQ$$SATQ$, $SATQ$c8fa7b76-8933-41cb-b3ac-6d1ca4af1b05$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9645f55e","external_id":"f13ab5d0-6fea-4c54-999b-ed0ead5c6e92","vaultid":"de2a8881-0765-4ada-a4e2-988e4f1ee27a","uId":"87ded3b1-a992-4496-b3d1-61a8de134da6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p><strong><span role=\"heading\" aria-level=\"2\">Text 1</span></strong></p>\n<p>For decades, bluegrass musicians have debated whether their genre should exclude influences from mainstream genres such as rock. Many insist that bluegrass is defined by its adherence to the folk music of the US South, out of which bluegrass emerged. Such &ldquo;purists,&rdquo; as they are known, regard the recordings of Bill Monroe, which established the bluegrass sound in the 1940s, as a standard against which the genre should still be measured.</p>\n<p>&nbsp;</p>\n<p><strong><span role=\"heading\" aria-level=\"2\">Text 2</span></strong></p>\n<p>Bluegrass isn&rsquo;t simply an extension of folk traditions into the era of recorded music. In reality, Bill Monroe created the bluegrass sound in the 1940s by combining Southern folk music with commercial genres that had arisen only a few decades before, such as jazz and the blues. Since bluegrass has always been a mixed genre, contemporary bluegrass musicians should not be forbidden from incorporating into it influences from rock and other mainstream genres.</p>","stem":"<p>Based on the texts, how would the author of Text 2 most likely regard the perspective of bluegrass purists, as described in Text 1?</p>","answerOptions":[{"id":"1b11c09d-0e00-407f-bf2c-f23ebc79f9da","content":"<p>As inconsistent, since bluegrass purists themselves enjoy other musical genres</p>"},{"id":"6afbe56b-b78d-40d2-8143-34bda6ed3e59","content":"<p>As unrealistic, since bluegrass purists have no way of enforcing their musical preferences</p>"},{"id":"81d17a2b-04a2-4cc9-a587-882616ba7b78","content":"<p>As shortsighted, because bluegrass could enlarge its audience by including influences from mainstream genres</p>"},{"id":"6eff68db-7a5b-4591-bf88-abd682f0a61a","content":"<p>As illogical, because the purists overlook crucial aspects of how the bluegrass sound first originated.</p>"}],"keys":["6eff68db-7a5b-4591-bf88-abd682f0a61a"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. According to Author 1, the &ldquo;purists&rdquo; argue that bluegrass should stick to its folk music roots. But Author 2 points out that this isn&rsquo;t how bluegrass emerged: it actually got its sound from a mix of folk, jazz, and blues. </p><p>Choice A is incorrect. There&rsquo;s nothing in Text 2 about what other genres the purists enjoy, so this inference about Author 2&rsquo;s views isn&rsquo;t supported. Choice B is incorrect. There&rsquo;s nothing in Text 2 about whether or how purists can enforce their preferences, so this inference about Author 2&rsquo;s views isn&rsquo;t supported. Choice C is incorrect. There&rsquo;s nothing in Text 2 about the size of bluegrass&rsquo;s audience, so this inference about Author 2&rsquo;s views isn&rsquo;t supported. </p>","parenttemplatename":"OSP-KA-CTC-M001","parenttemplateid":"","templateclusterid":"c8fa7b76-8933-41cb-b3ac-6d1ca4af1b05","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$9671d61d$SATQ$, $SATQ$625f5ce2-ea7f-47ab-bc02-5689c89e0902$SATQ$::uuid, $SATQ$5345d912-40f4-480d-a4de-cd8c15f6de2f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Claude McKay&rsquo;s 1922 poem &ldquo;Morning Joy.&rdquo; The speaker is looking out a window and observing a wold, or large area of land.</p>
<p>&nbsp;</p>
<blockquote class="dap_poemexcerpt">
<p>At night the wide and level stretch of wold,</p>
<p>Which at high noon had basked in quiet gold,</p>
<p>Far as the eye could see was ghostly white;</p>
<p>Dark was the night save for the snow&rsquo;s weird light.</p>
<p>&nbsp;</p>
<p>I <span role="region" aria-label="Referenced Content"><u>drew</u></span> the shades far down, crept into bed;</p>
<p>Hearing the cold wind moaning overhead</p>
<p>Through the sad pines, my soul, catching its pain,</p>
<p>Went sorrowing with it across the plain.</p>
</blockquote>$SATQ$, $SATQ$<p>As used in the text, what does the word &ldquo;drew&rdquo; most nearly mean?</p>$SATQ$, $SATQ$[{"id":"6e65b5cc-17c2-4a42-80e7-abf49c22dd0f","content":"<p>Pulled</p>"},{"id":"d36ffbb2-b51c-4d50-a4bf-873e6f7b7d8e","content":"<p>Drained</p>"},{"id":"cf7bc2d4-de4a-4bd7-a2d3-3b132e05b037","content":"<p>Inspired</p>"},{"id":"fa6924db-2411-449f-a8f7-f9ef73683834","content":"<p>Sketched</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["6e65b5cc-17c2-4a42-80e7-abf49c22dd0f"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because as used in the text, &ldquo;drew&rdquo; most nearly means pulled. In the text, the speaker stands at a window, looking out on a landscape at night. The speaker then &ldquo;drew the shades far down, crept into bed.&rdquo; That is, the speaker pulled down, or lowered, the shades until they were completely shut before going to sleep.&nbsp;</p><p>Choice B is incorrect. Although in some contexts, &ldquo;drew&rdquo; can refer to draining or removing liquid, especially water, as when someone draws water from a well, in this context it refers to the speaker pulling down window shades for the night. Choice C is incorrect. In some contexts, &ldquo;drew&rdquo; can be used to describe how a person or thing inspires, or elicits, a response from someone, as when a performer draws applause from an audience. But in this context it refers to the speaker pulling down window shades for the night.&nbsp;Choice D is incorrect. Although &ldquo;drew&rdquo; has several meanings, including sketched, or illustrated with a pen or pencil, in this context it refers to the speaker pulling down window shades for the night. </p>$SATQ$, false, 0, $SATQ$OSP-039-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$572fb30a-de4c-4766-865e-a0a138644b1e$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9671d61d","external_id":"625f5ce2-ea7f-47ab-bc02-5689c89e0902","vaultid":"5345d912-40f4-480d-a4de-cd8c15f6de2f","uId":"6dc03a2b-22f7-44c6-a4c7-e4909b64483f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The following text is from Claude McKay&rsquo;s 1922 poem &ldquo;Morning Joy.&rdquo; The speaker is looking out a window and observing a wold, or large area of land.</p>\n<p>&nbsp;</p>\n<blockquote class=\"dap_poemexcerpt\">\n<p>At night the wide and level stretch of wold,</p>\n<p>Which at high noon had basked in quiet gold,</p>\n<p>Far as the eye could see was ghostly white;</p>\n<p>Dark was the night save for the snow&rsquo;s weird light.</p>\n<p>&nbsp;</p>\n<p>I <span role=\"region\" aria-label=\"Referenced Content\"><u>drew</u></span> the shades far down, crept into bed;</p>\n<p>Hearing the cold wind moaning overhead</p>\n<p>Through the sad pines, my soul, catching its pain,</p>\n<p>Went sorrowing with it across the plain.</p>\n</blockquote>","stem":"<p>As used in the text, what does the word &ldquo;drew&rdquo; most nearly mean?</p>","answerOptions":[{"id":"6e65b5cc-17c2-4a42-80e7-abf49c22dd0f","content":"<p>Pulled</p>"},{"id":"d36ffbb2-b51c-4d50-a4bf-873e6f7b7d8e","content":"<p>Drained</p>"},{"id":"cf7bc2d4-de4a-4bd7-a2d3-3b132e05b037","content":"<p>Inspired</p>"},{"id":"fa6924db-2411-449f-a8f7-f9ef73683834","content":"<p>Sketched</p>"}],"keys":["6e65b5cc-17c2-4a42-80e7-abf49c22dd0f"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because as used in the text, &ldquo;drew&rdquo; most nearly means pulled. In the text, the speaker stands at a window, looking out on a landscape at night. The speaker then &ldquo;drew the shades far down, crept into bed.&rdquo; That is, the speaker pulled down, or lowered, the shades until they were completely shut before going to sleep.&nbsp;</p><p>Choice B is incorrect. Although in some contexts, &ldquo;drew&rdquo; can refer to draining or removing liquid, especially water, as when someone draws water from a well, in this context it refers to the speaker pulling down window shades for the night. Choice C is incorrect. In some contexts, &ldquo;drew&rdquo; can be used to describe how a person or thing inspires, or elicits, a response from someone, as when a performer draws applause from an audience. But in this context it refers to the speaker pulling down window shades for the night.&nbsp;Choice D is incorrect. Although &ldquo;drew&rdquo; has several meanings, including sketched, or illustrated with a pen or pencil, in this context it refers to the speaker pulling down window shades for the night. </p>","parenttemplatename":"OSP-039-WIC","parenttemplateid":"","templateclusterid":"572fb30a-de4c-4766-865e-a0a138644b1e","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959321,"updateDate":1691007959321}$SATQ$::jsonb, 1691007959321, 1691007959321),
    ($SATQ$96f3accc$SATQ$, $SATQ$29e37d20-b74b-4e20-a838-3fa83260cb28$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 1</strong></span></p>
<p>When the 50-second-long film <em>Arrival of the Train</em>&mdash;which depicts what its title says, a train pulling into a station&mdash;was first shown publicly in 1896, spectators, na&iuml;ve to the new medium of film and seeing a train appearing to come directly at them, leaped from their seats and fled the room. This moment marks a major cultural shift: a new way of representing and seeing the world had arrived with that train, and nothing would ever be the same.</p>
<p>&nbsp;</p>
<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 2</strong></span></p>
<p>The fact that there is no contemporary evidence that the first audience of <em>Arrival of the Train</em> was alarmed has not stopped the story from becoming canonical, even among film historians. But that phenomenon itself is highly revealing. Our belief that the coming of film was transformative is so strong that we invented and keep retelling a founding myth that divides cultural history into a (na&iuml;ve) &ldquo;before&rdquo; and (sophisticated) &ldquo;after.&rdquo;&nbsp;</p>$SATQ$, $SATQ$<p>Based on the texts, the author of Text 2 would most likely agree with which statement about the description of the first showing of <em>Arrival of the Train</em> in Text 1?</p>$SATQ$, $SATQ$[{"id":"e11db7a6-f24b-486c-8955-f6510bc10d0e","content":"<p>It is more motivated by a perception of the significance of the invention of film than by facts.&nbsp;</p>"},{"id":"d1b948a4-cac1-4517-979c-48da4ec79f98","content":"<p>It expresses a view about the transformative nature of film that film historians tend to regard as na&iuml;ve.</p>"},{"id":"901dde32-f39d-48c4-9192-839093d3074c","content":"<p>It is not based on evidence and reflects film historians&rsquo; belief that they are more sophisticated than today&rsquo;s audiences.</p>"},{"id":"f7282c79-23af-4839-a054-40bd92145a07","content":"<p>It reflects a misconception that is widely believed because it captures early film audiences&rsquo; sense that the new medium was alarming.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["e11db7a6-f24b-486c-8955-f6510bc10d0e"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it provides a statement about the description of the first showing of <em>Arrival of the Train</em> in Text 1 that, based on the texts, the author of Text 2 would most likely agree with. Text 1 indicates that members of the audience, unaccustomed to the new medium of film and believing that they were looking at a real oncoming train, allegedly reacted to the film with alarm. Text 1 then goes on to treat this anecdote as a factual account of the film&rsquo;s first showing, interpreting it as a moment that marked a "major cultural shift." In contrast, the author of Text 2 indicates that though the story of the film&rsquo;s first showing has become "canonical," or widely accepted, there is no contemporary evidence to support the idea that the audience reacted as Text 1 describes. Text 2 goes on to explain that this factually questionable description likely persists because it functions as a "founding myth" that reinforces a widespread belief in the profoundly transformative nature of the invention of film. This indicates that the author of Text 2 would likely see the description in Text 1 as motivated primarily by cultural perceptions about film&rsquo;s significance rather than by documented historical facts.</p><p>Choice B is incorrect because the author of Text 2 doesn&rsquo;t suggest that film historians regard the view about film&rsquo;s transformative nature as na&iuml;ve. On the contrary, Text 2 states that the story of the first showing of <em>Arrival of the Train</em> has become "canonical, even among film historians," indicating that historians broadly accept this narrative as a compelling illustration of film&rsquo;s impact, not that they regard either the narrative or the views it conveys about the transformative nature of film as na&iuml;ve. Text 2 refers to a "(na&iuml;ve) &lsquo;before&rsquo;" in cultural history, but this is describing how the myth itself characterizes pre-film audiences, not how historians regard views about the transformative nature of film. Choice C is incorrect. While the author of Text 2 does indicate that the story of the audience&rsquo;s reaction to <em>Arrival of the Train </em>described in Text 1 is a myth that lacks evidence, the text doesn&rsquo;t suggest that the story reflects the fact that film historians believe themselves to be more sophisticated than modern audiences are. Rather, Text 2 suggests that the story persists because of a collective cultural belief, which historians share, in the profound impact of the invention of film. Moreover, the "na&iuml;ve" versus "sophisticated" distinction mentioned in Text 2 refers to how the myth characterizes audiences before and after the invention of film; it doesn&rsquo;t characterize modern audiences versus film historians. Choice D is incorrect. Although the author of Text 2 would agree that the description of the first showing of <em>Arrival of the Train</em> in Text 1 reflects a misconception, the author wouldn&rsquo;t agree that widespread belief in the misconception can be attributed to the fact that it accurately captures early audiences&rsquo; actual sense of alarm. In fact, the misconception identified by the author of Text 2 concerns the accuracy of the audience&rsquo;s alleged reaction; the author questions whether early audiences were alarmed at all, stating there is "no contemporary evidence" that they reacted in this way. According to Text 2, the description is widely believed not because it accurately captures historical reactions but because it serves as a "founding myth" that supports a belief in film&rsquo;s transformative cultural impact.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"96f3accc","external_id":"29e37d20-b74b-4e20-a838-3fa83260cb28","vaultid":null,"uId":"8316e36b-303e-456a-9d01-7776e6a72057","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 1</strong></span></p>\n<p>When the 50-second-long film <em>Arrival of the Train</em>&mdash;which depicts what its title says, a train pulling into a station&mdash;was first shown publicly in 1896, spectators, na&iuml;ve to the new medium of film and seeing a train appearing to come directly at them, leaped from their seats and fled the room. This moment marks a major cultural shift: a new way of representing and seeing the world had arrived with that train, and nothing would ever be the same.</p>\n<p>&nbsp;</p>\n<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 2</strong></span></p>\n<p>The fact that there is no contemporary evidence that the first audience of <em>Arrival of the Train</em> was alarmed has not stopped the story from becoming canonical, even among film historians. But that phenomenon itself is highly revealing. Our belief that the coming of film was transformative is so strong that we invented and keep retelling a founding myth that divides cultural history into a (na&iuml;ve) &ldquo;before&rdquo; and (sophisticated) &ldquo;after.&rdquo;&nbsp;</p>","stem":"<p>Based on the texts, the author of Text 2 would most likely agree with which statement about the description of the first showing of <em>Arrival of the Train</em> in Text 1?</p>","answerOptions":[{"id":"e11db7a6-f24b-486c-8955-f6510bc10d0e","content":"<p>It is more motivated by a perception of the significance of the invention of film than by facts.&nbsp;</p>"},{"id":"d1b948a4-cac1-4517-979c-48da4ec79f98","content":"<p>It expresses a view about the transformative nature of film that film historians tend to regard as na&iuml;ve.</p>"},{"id":"901dde32-f39d-48c4-9192-839093d3074c","content":"<p>It is not based on evidence and reflects film historians&rsquo; belief that they are more sophisticated than today&rsquo;s audiences.</p>"},{"id":"f7282c79-23af-4839-a054-40bd92145a07","content":"<p>It reflects a misconception that is widely believed because it captures early film audiences&rsquo; sense that the new medium was alarming.</p>"}],"keys":["e11db7a6-f24b-486c-8955-f6510bc10d0e"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it provides a statement about the description of the first showing of <em>Arrival of the Train</em> in Text 1 that, based on the texts, the author of Text 2 would most likely agree with. Text 1 indicates that members of the audience, unaccustomed to the new medium of film and believing that they were looking at a real oncoming train, allegedly reacted to the film with alarm. Text 1 then goes on to treat this anecdote as a factual account of the film&rsquo;s first showing, interpreting it as a moment that marked a \"major cultural shift.\" In contrast, the author of Text 2 indicates that though the story of the film&rsquo;s first showing has become \"canonical,\" or widely accepted, there is no contemporary evidence to support the idea that the audience reacted as Text 1 describes. Text 2 goes on to explain that this factually questionable description likely persists because it functions as a \"founding myth\" that reinforces a widespread belief in the profoundly transformative nature of the invention of film. This indicates that the author of Text 2 would likely see the description in Text 1 as motivated primarily by cultural perceptions about film&rsquo;s significance rather than by documented historical facts.</p><p>Choice B is incorrect because the author of Text 2 doesn&rsquo;t suggest that film historians regard the view about film&rsquo;s transformative nature as na&iuml;ve. On the contrary, Text 2 states that the story of the first showing of <em>Arrival of the Train</em> has become \"canonical, even among film historians,\" indicating that historians broadly accept this narrative as a compelling illustration of film&rsquo;s impact, not that they regard either the narrative or the views it conveys about the transformative nature of film as na&iuml;ve. Text 2 refers to a \"(na&iuml;ve) &lsquo;before&rsquo;\" in cultural history, but this is describing how the myth itself characterizes pre-film audiences, not how historians regard views about the transformative nature of film. Choice C is incorrect. While the author of Text 2 does indicate that the story of the audience&rsquo;s reaction to <em>Arrival of the Train </em>described in Text 1 is a myth that lacks evidence, the text doesn&rsquo;t suggest that the story reflects the fact that film historians believe themselves to be more sophisticated than modern audiences are. Rather, Text 2 suggests that the story persists because of a collective cultural belief, which historians share, in the profound impact of the invention of film. Moreover, the \"na&iuml;ve\" versus \"sophisticated\" distinction mentioned in Text 2 refers to how the myth characterizes audiences before and after the invention of film; it doesn&rsquo;t characterize modern audiences versus film historians. Choice D is incorrect. Although the author of Text 2 would agree that the description of the first showing of <em>Arrival of the Train</em> in Text 1 reflects a misconception, the author wouldn&rsquo;t agree that widespread belief in the misconception can be attributed to the fact that it accurately captures early audiences&rsquo; actual sense of alarm. In fact, the misconception identified by the author of Text 2 concerns the accuracy of the audience&rsquo;s alleged reaction; the author questions whether early audiences were alarmed at all, stating there is \"no contemporary evidence\" that they reacted in this way. According to Text 2, the description is widely believed not because it accurately captures historical reactions but because it serves as a \"founding myth\" that supports a belief in film&rsquo;s transformative cultural impact.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061176,"updateDate":1755117061176}$SATQ$::jsonb, 1755117061176, 1755117061176),
    ($SATQ$97360a00$SATQ$, $SATQ$123877dc-02fe-4b9c-8afa-a751cfa3b840$SATQ$::uuid, $SATQ$87c312d8-42fa-461c-b590-c215eeceb2fd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Gwendolyn Bennett&rsquo;s 1926 poem &ldquo;Street Lamps in Early Spring.&rdquo; </p>
<p style="padding-left:1em;">Night wears a garment<br>All velvet soft, all violet blue...&nbsp;<br>And over her face she draws a veil<br>As shimmering fine as floating dew...&nbsp;<br>And here and there<br>In the black of her hair<br>The subtle hands of Night<br>Move slowly with their gem-starred light.</p>$SATQ$, $SATQ$<p>Which choice best describes the overall structure of the text?</p>$SATQ$, $SATQ$[{"id":"63053b72-8b77-448c-a416-d6f89a816290","content":"<p>It presents alternating descriptions of night in a rural area and in a city.</p>"},{"id":"65dca31b-cb00-4066-955e-bb007b3fea33","content":"<p>It sketches an image of nightfall, then an image of sunrise.</p>"},{"id":"1b13404c-f6ed-4eef-9679-5a72acd726d2","content":"<p>It makes an extended comparison of night to a human being.</p>"},{"id":"e8f807cb-3e05-4662-bb9d-984c6e9eb1bb","content":"<p>It portrays how night changes from one season of the year to the next.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["1b13404c-f6ed-4eef-9679-5a72acd726d2"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most accurately describes the overall structure of the text. Throughout the text, the speaker characterizes nighttime as if it were a person who wears clothing (&ldquo;a garment&rdquo; that is &ldquo;velvet soft&rdquo; and &ldquo;violet blue&rdquo;) and a veil &ldquo;over her face&rdquo; and who moves her hands &ldquo;slowly with their gem-starred light&rdquo; through her dark hair. Thus, the text is structured as an extended comparison of night to a human being. </p><p>Choice A is incorrect because the text never mentions any particular location; instead, it focuses on presenting a single description of night as a person with certain clothing and features. Choice B is incorrect because the text doesn&rsquo;t make any reference to the sun or sunrise; instead, it focuses on presenting a single image of night as a person with certain clothing and features. Choice D is incorrect. Rather than describing how nighttime changes seasonally (or in any other way), the text presents a single image of night as a person with certain clothing and features. </p>$SATQ$, false, 0, $SATQ$OSP-035-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$f158e3c6-a9cf-4ca2-ba3f-876a150c546b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"97360a00","external_id":"123877dc-02fe-4b9c-8afa-a751cfa3b840","vaultid":"87c312d8-42fa-461c-b590-c215eeceb2fd","uId":"d638bcde-7d1d-49a9-bc6d-25921dd34d83","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The following text is adapted from Gwendolyn Bennett&rsquo;s 1926 poem &ldquo;Street Lamps in Early Spring.&rdquo; </p>\n<p style=\"padding-left:1em;\">Night wears a garment<br>All velvet soft, all violet blue...&nbsp;<br>And over her face she draws a veil<br>As shimmering fine as floating dew...&nbsp;<br>And here and there<br>In the black of her hair<br>The subtle hands of Night<br>Move slowly with their gem-starred light.</p>","stem":"<p>Which choice best describes the overall structure of the text?</p>","answerOptions":[{"id":"63053b72-8b77-448c-a416-d6f89a816290","content":"<p>It presents alternating descriptions of night in a rural area and in a city.</p>"},{"id":"65dca31b-cb00-4066-955e-bb007b3fea33","content":"<p>It sketches an image of nightfall, then an image of sunrise.</p>"},{"id":"1b13404c-f6ed-4eef-9679-5a72acd726d2","content":"<p>It makes an extended comparison of night to a human being.</p>"},{"id":"e8f807cb-3e05-4662-bb9d-984c6e9eb1bb","content":"<p>It portrays how night changes from one season of the year to the next.</p>"}],"keys":["1b13404c-f6ed-4eef-9679-5a72acd726d2"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most accurately describes the overall structure of the text. Throughout the text, the speaker characterizes nighttime as if it were a person who wears clothing (&ldquo;a garment&rdquo; that is &ldquo;velvet soft&rdquo; and &ldquo;violet blue&rdquo;) and a veil &ldquo;over her face&rdquo; and who moves her hands &ldquo;slowly with their gem-starred light&rdquo; through her dark hair. Thus, the text is structured as an extended comparison of night to a human being. </p><p>Choice A is incorrect because the text never mentions any particular location; instead, it focuses on presenting a single description of night as a person with certain clothing and features. Choice B is incorrect because the text doesn&rsquo;t make any reference to the sun or sunrise; instead, it focuses on presenting a single image of night as a person with certain clothing and features. Choice D is incorrect. Rather than describing how nighttime changes seasonally (or in any other way), the text presents a single image of night as a person with certain clothing and features. </p>","parenttemplatename":"OSP-035-TSP","parenttemplateid":"","templateclusterid":"f158e3c6-a9cf-4ca2-ba3f-876a150c546b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959320,"updateDate":1691007959320}$SATQ$::jsonb, 1691007959320, 1691007959320),
    ($SATQ$975b0602$SATQ$, $SATQ$97a5db5c-98a1-4fac-97ef-117af4272b34$SATQ$::uuid, $SATQ$79207cd5-3d6b-4c38-8772-450797962f68$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>A number of Indigenous politicians have been elected to the United States Congress since 2000 as members of the country&rsquo;s two established political parties. In Canada and several Latin American countries, on the other hand, Indigenous people have formed their own political parties to advance candidates who will advocate for the interests of their communities. This movement has been particularly successful in Ecuador, where Guadalupe Llori, a member of the Indigenous party known as Pachakutik, was elected president of the National Assembly in 2021.</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"0f70b004-ad6a-4907-83bc-ae0e35f1ee94","content":"<p>To trace the history of an Indigenous political movement and speculate about its future development</p>"},{"id":"e6d67197-95fb-475c-a4bb-7f4b83b8970e","content":"<p>To argue that Indigenous politicians in the United States should form their own political party</p>"},{"id":"4b0f7bc5-8a55-4334-858c-495f5816da0c","content":"<p>To highlight two approaches to achieving political representation for Indigenous people</p>"},{"id":"21b2f1b5-7284-4af3-9db3-1c57054c60df","content":"<p>To consider how Indigenous politicians in the United States have influenced Indigenous politicians in Canada and Latin America</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["4b0f7bc5-8a55-4334-858c-495f5816da0c"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most accurately describes the main purpose of the text, which is to illustrate two approaches that Indigenous politicians have taken to achieve political representation for their communities. The text begins by explaining that one approach is exemplified by Indigenous politicians in the United States who, in an effort to ensure that the interests of their communities are represented in government, joined preexisting political parties and were subsequently elected to Congress. The text goes on to highlight a second approach adopted by Indigenous leaders in Canada and several Latin American countries: rather than joining established political parties, many Indigenous politicians in these countries have instead formed their own parties to promote candidates for office who support causes that are important to their communities.&nbsp;</p><p>Choice A is incorrect because the text&rsquo;s focus is on the contrasting approaches adopted by different Indigenous political movements in different countries; thus, it isn&rsquo;t accurate to say that the text traces the history of one political movement. Moreover, the text only discusses examples from 2000 to 2021, a relatively short period of time; therefore, it provides very little in the way of discussion of larger historical developments, nor does it make any predictions about how these movements might continue to develop in the future. Choice B is incorrect because the text never urges Indigenous politicians in the US to alter their strategy of striving for representation through the established political parties, nor does it suggest that this strategy is inferior to that of Indigenous politicians in Canada and Latin America, who have formed their own parties. In fact, the text notes that both strategies have resulted in the election of Indigenous politicians to national governments. Choice D is incorrect because the text never suggests that Indigenous politicians in the US have influenced those in Canada and Latin America; instead, it stresses how Indigenous politicians&rsquo; approach toward achieving representation in the US government has differed from the approach Indigenous politicians have taken to achieve representation in national governments elsewhere in the Americas. </p>$SATQ$, false, 0, $SATQ$OSP-049-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$6667ff27-e2b8-4b0a-a11e-19ba249f3745$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"975b0602","external_id":"97a5db5c-98a1-4fac-97ef-117af4272b34","vaultid":"79207cd5-3d6b-4c38-8772-450797962f68","uId":"69ffa021-54b6-43c3-8d07-59cd5f399958","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>A number of Indigenous politicians have been elected to the United States Congress since 2000 as members of the country&rsquo;s two established political parties. In Canada and several Latin American countries, on the other hand, Indigenous people have formed their own political parties to advance candidates who will advocate for the interests of their communities. This movement has been particularly successful in Ecuador, where Guadalupe Llori, a member of the Indigenous party known as Pachakutik, was elected president of the National Assembly in 2021.</p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"0f70b004-ad6a-4907-83bc-ae0e35f1ee94","content":"<p>To trace the history of an Indigenous political movement and speculate about its future development</p>"},{"id":"e6d67197-95fb-475c-a4bb-7f4b83b8970e","content":"<p>To argue that Indigenous politicians in the United States should form their own political party</p>"},{"id":"4b0f7bc5-8a55-4334-858c-495f5816da0c","content":"<p>To highlight two approaches to achieving political representation for Indigenous people</p>"},{"id":"21b2f1b5-7284-4af3-9db3-1c57054c60df","content":"<p>To consider how Indigenous politicians in the United States have influenced Indigenous politicians in Canada and Latin America</p>"}],"keys":["4b0f7bc5-8a55-4334-858c-495f5816da0c"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most accurately describes the main purpose of the text, which is to illustrate two approaches that Indigenous politicians have taken to achieve political representation for their communities. The text begins by explaining that one approach is exemplified by Indigenous politicians in the United States who, in an effort to ensure that the interests of their communities are represented in government, joined preexisting political parties and were subsequently elected to Congress. The text goes on to highlight a second approach adopted by Indigenous leaders in Canada and several Latin American countries: rather than joining established political parties, many Indigenous politicians in these countries have instead formed their own parties to promote candidates for office who support causes that are important to their communities.&nbsp;</p><p>Choice A is incorrect because the text&rsquo;s focus is on the contrasting approaches adopted by different Indigenous political movements in different countries; thus, it isn&rsquo;t accurate to say that the text traces the history of one political movement. Moreover, the text only discusses examples from 2000 to 2021, a relatively short period of time; therefore, it provides very little in the way of discussion of larger historical developments, nor does it make any predictions about how these movements might continue to develop in the future. Choice B is incorrect because the text never urges Indigenous politicians in the US to alter their strategy of striving for representation through the established political parties, nor does it suggest that this strategy is inferior to that of Indigenous politicians in Canada and Latin America, who have formed their own parties. In fact, the text notes that both strategies have resulted in the election of Indigenous politicians to national governments. Choice D is incorrect because the text never suggests that Indigenous politicians in the US have influenced those in Canada and Latin America; instead, it stresses how Indigenous politicians&rsquo; approach toward achieving representation in the US government has differed from the approach Indigenous politicians have taken to achieve representation in national governments elsewhere in the Americas. </p>","parenttemplatename":"OSP-049-TSP","parenttemplateid":"","templateclusterid":"6667ff27-e2b8-4b0a-a11e-19ba249f3745","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959323,"updateDate":1691007959323}$SATQ$::jsonb, 1691007959323, 1691007959323),
    ($SATQ$97ab5669$SATQ$, $SATQ$e86701d5-1e07-4cfd-bac3-cb42173eff9d$SATQ$::uuid, $SATQ$c8910f83-325d-44ad-9732-44d2c6c2428f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Former astronaut Ellen Ochoa says that although she doesn&rsquo;t have a definite idea of when it might happen, she <span aria-hidden="true">______</span><span class="sr-only">blank</span> that humans will someday need to be able to live in other environments than those found on Earth. This conjecture informs her interest in future research missions to the moon.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"67120e9f-9512-4cfd-beb0-583410b42c92","content":"<p>demands</p>"},{"id":"eecaa835-0353-4922-bda8-1898e9351568","content":"<p>speculates</p>"},{"id":"c69502ea-f897-42bb-ac97-5930b7cd5d1c","content":"<p>doubts</p>"},{"id":"12a88f84-46a2-4e5d-b210-ec3a1407c8c5","content":"<p>establishes</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["eecaa835-0353-4922-bda8-1898e9351568"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Ochoa&rsquo;s prediction that humans will one day need to live in places other than Earth. As used in this context, &ldquo;speculates&rdquo; would mean puts forward an idea without firm evidence. The text states that Ochoa &ldquo;doesn&rsquo;t have a definite idea&rdquo; about when humans might need to live in other environments and characterizes Ochoa&rsquo;s prediction as a &ldquo;conjecture,&rdquo; or a conclusion presented without convincing evidence. This context indicates that Ochoa speculates when she makes this prediction.&nbsp;</p><p>Choice A is incorrect because saying that Ochoa &ldquo;demands,&rdquo; or insists or requires, that humans will one day need to live in other environments than Earth&rsquo;s would not make sense in context. The text indicates that she&rsquo;s unsure about the timing but hypothesizes that it will someday happen. Choice C is incorrect because &nbsp;saying that Ochoa &ldquo;doubts,&rdquo; or questions or disbelieves, that humans will one day need to live in other environments than Earth&rsquo;s would not make sense in context. The text indicates that although Ochoa is unsure about the timing, she hypothesizes that humans will need to live in places other than Earth and encourages research into future travel to the moon. Choice D is incorrect because &nbsp;saying that Ochoa &ldquo;establishes,&rdquo; or proves, that humans will one day need to live in other environments than Earth&rsquo;s would not make sense in context. Rather than stating that Ochoa discusses her idea with certainty and supports it with evidence, the text indicates that Ochoa is unsure about when humans might need to live in other environments. </p>$SATQ$, false, 0, $SATQ$OSP-906-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$c248a221-e817-48b2-8596-993ee8385ed2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"97ab5669","external_id":"e86701d5-1e07-4cfd-bac3-cb42173eff9d","vaultid":"c8910f83-325d-44ad-9732-44d2c6c2428f","uId":"0d63ed24-2aa7-4a09-ae42-f3391bc21036","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Former astronaut Ellen Ochoa says that although she doesn&rsquo;t have a definite idea of when it might happen, she <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> that humans will someday need to be able to live in other environments than those found on Earth. This conjecture informs her interest in future research missions to the moon.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"67120e9f-9512-4cfd-beb0-583410b42c92","content":"<p>demands</p>"},{"id":"eecaa835-0353-4922-bda8-1898e9351568","content":"<p>speculates</p>"},{"id":"c69502ea-f897-42bb-ac97-5930b7cd5d1c","content":"<p>doubts</p>"},{"id":"12a88f84-46a2-4e5d-b210-ec3a1407c8c5","content":"<p>establishes</p>"}],"keys":["eecaa835-0353-4922-bda8-1898e9351568"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Ochoa&rsquo;s prediction that humans will one day need to live in places other than Earth. As used in this context, &ldquo;speculates&rdquo; would mean puts forward an idea without firm evidence. The text states that Ochoa &ldquo;doesn&rsquo;t have a definite idea&rdquo; about when humans might need to live in other environments and characterizes Ochoa&rsquo;s prediction as a &ldquo;conjecture,&rdquo; or a conclusion presented without convincing evidence. This context indicates that Ochoa speculates when she makes this prediction.&nbsp;</p><p>Choice A is incorrect because saying that Ochoa &ldquo;demands,&rdquo; or insists or requires, that humans will one day need to live in other environments than Earth&rsquo;s would not make sense in context. The text indicates that she&rsquo;s unsure about the timing but hypothesizes that it will someday happen. Choice C is incorrect because &nbsp;saying that Ochoa &ldquo;doubts,&rdquo; or questions or disbelieves, that humans will one day need to live in other environments than Earth&rsquo;s would not make sense in context. The text indicates that although Ochoa is unsure about the timing, she hypothesizes that humans will need to live in places other than Earth and encourages research into future travel to the moon. Choice D is incorrect because &nbsp;saying that Ochoa &ldquo;establishes,&rdquo; or proves, that humans will one day need to live in other environments than Earth&rsquo;s would not make sense in context. Rather than stating that Ochoa discusses her idea with certainty and supports it with evidence, the text indicates that Ochoa is unsure about when humans might need to live in other environments. </p>","parenttemplatename":"OSP-906-WIC","parenttemplateid":"","templateclusterid":"c248a221-e817-48b2-8596-993ee8385ed2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959354,"updateDate":1691007959354}$SATQ$::jsonb, 1691007959354, 1691007959354),
    ($SATQ$97ca2cda$SATQ$, $SATQ$fa3d1dfb-6e23-4719-8784-4d2976c38943$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In the early days of television in the 1940s, many people thought that US television programs would rely on the financial support of ad agencies and commercial sponsors, much like radio did. But advertisers hesitated to jump into a new space, <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">particularly at a time when the manufacturing of new television sets was stalled due to the US&rsquo;s involvement in World War II.</span> Broadcasters, like the National Broadcasting Company (NBC), needed to persuade advertisers to support their programming despite not knowing whether there would be a robust television audience to begin with.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined phrase in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"21cc8975-cf91-4f2e-b9eb-d9433944ac76","content":"<p>It compares the beginnings of radio programming with the beginnings of television programming in the United States.&nbsp;</p>"},{"id":"2f3ede60-40c6-40b7-a21f-7aac5d6e289b","content":"<p>It identifies a specific reason behind some advertisers&rsquo; hesitance to support television.</p>"},{"id":"08a614c2-cc17-44f7-9b01-af50d1e5457d","content":"<p>It describes how broadcasters attempted to convince advertisers to support television.</p>"},{"id":"f1c4cf7c-902f-4da5-b547-2edee9280fbb","content":"<p>It explains why a type of television programming was popular at the time.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["2f3ede60-40c6-40b7-a21f-7aac5d6e289b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it accurately describes the function of the underlined phrase in the text as a whole. According to the text, advertisers were reluctant to support television in its early days. The underlined phrase then indicates that this reluctance was partly due to the US&rsquo;s involvement in World War II, which hindered television production. Thus, the underlined phrase identifies a specific reason behind some advertisers&rsquo; hesitance to support television.</p><p>Choice A is incorrect. The text merely mentions that television was expected to be financed through advertising, as radio was at the time. Nothing in the text compares the origins of radio and television. Choice C is incorrect. The underlined phrase focuses on a reason advertisers were reluctant to support television, not measures taken to convince advertisers to support television. Choice D is incorrect. The underlined phrase focuses on a reason advertisers were reluctant to support television, not what types of television programming were popular.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"97ca2cda","external_id":"fa3d1dfb-6e23-4719-8784-4d2976c38943","vaultid":null,"uId":"80a445fc-7451-4feb-9c70-fef18d824c85","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In the early days of television in the 1940s, many people thought that US television programs would rely on the financial support of ad agencies and commercial sponsors, much like radio did. But advertisers hesitated to jump into a new space, <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">particularly at a time when the manufacturing of new television sets was stalled due to the US&rsquo;s involvement in World War II.</span> Broadcasters, like the National Broadcasting Company (NBC), needed to persuade advertisers to support their programming despite not knowing whether there would be a robust television audience to begin with.</p>","stem":"<p>Which choice best describes the function of the underlined phrase in the text as a whole?</p>","answerOptions":[{"id":"21cc8975-cf91-4f2e-b9eb-d9433944ac76","content":"<p>It compares the beginnings of radio programming with the beginnings of television programming in the United States.&nbsp;</p>"},{"id":"2f3ede60-40c6-40b7-a21f-7aac5d6e289b","content":"<p>It identifies a specific reason behind some advertisers&rsquo; hesitance to support television.</p>"},{"id":"08a614c2-cc17-44f7-9b01-af50d1e5457d","content":"<p>It describes how broadcasters attempted to convince advertisers to support television.</p>"},{"id":"f1c4cf7c-902f-4da5-b547-2edee9280fbb","content":"<p>It explains why a type of television programming was popular at the time.</p>"}],"keys":["2f3ede60-40c6-40b7-a21f-7aac5d6e289b"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it accurately describes the function of the underlined phrase in the text as a whole. According to the text, advertisers were reluctant to support television in its early days. The underlined phrase then indicates that this reluctance was partly due to the US&rsquo;s involvement in World War II, which hindered television production. Thus, the underlined phrase identifies a specific reason behind some advertisers&rsquo; hesitance to support television.</p><p>Choice A is incorrect. The text merely mentions that television was expected to be financed through advertising, as radio was at the time. Nothing in the text compares the origins of radio and television. Choice C is incorrect. The underlined phrase focuses on a reason advertisers were reluctant to support television, not measures taken to convince advertisers to support television. Choice D is incorrect. The underlined phrase focuses on a reason advertisers were reluctant to support television, not what types of television programming were popular.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669215,"updateDate":1743430669215}$SATQ$::jsonb, 1743430669215, 1743430669215),
    ($SATQ$97e5bf55$SATQ$, $SATQ$7a76d554-0375-4e2a-b0b2-5df72b2ce5b5$SATQ$::uuid, $SATQ$ee594b6b-07bc-478f-b2c8-f6d7be38051b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p><strong>Text 1</strong></p>
<p>In 1916, H. Dugdale Sykes disputed claims that <em>The Two Noble Kinsmen</em> was coauthored by William Shakespeare and John Fletcher. Sykes felt Fletcher&rsquo;s contributions to the play were obvious&mdash;Fletcher had a distinct style in his other plays, so much so that lines with that style were considered sufficient evidence of Fletcher&rsquo;s authorship. But for the lines not deemed to be by Fletcher, Sykes felt that their depiction of women indicated that their author was not Shakespeare but Philip Massinger.</p>
<p><strong>Text 2</strong></p>
<p>Scholars have accepted <em>The Two Noble Kinsmen</em> as coauthored by Shakespeare since the 1970s: it appears in all major one-volume editions of Shakespeare&rsquo;s complete works. Though scholars disagree about who wrote what exactly, it is generally held that on the basis of style, Shakespeare wrote all of the first act and most of the last, while John Fletcher authored most of the three middle acts.</p>$SATQ$, $SATQ$<p>Based on the texts, both Sykes in Text 1 and the scholars in Text 2 would most likely agree with which statement?</p>$SATQ$, $SATQ$[{"id":"8f908222-9d83-4c63-a857-5f6b396e9e6d","content":"<p>John Fletcher&rsquo;s writing has a unique, readily identifiable style.</p>"},{"id":"c86d3827-3ab8-4586-a677-63e99e545a4c","content":"<p>The women characters in John Fletcher&rsquo;s plays are similar to the women characters in Philip Massinger&rsquo;s plays.</p>"},{"id":"ecfbfbb4-e49f-4901-a1a8-e6a3dbec8c14","content":"<p><em>The Two Noble Kinsmen</em> belongs in one-volume compilations of Shakespeare&rsquo;s complete plays.</p>"},{"id":"a934d487-6b03-4a3e-a380-4e10b227203f","content":"<p>Philip Massinger&rsquo;s style in the first and last acts of <em>The Two Noble Kinsmen</em> is an homage to Shakespeare&rsquo;s style.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["8f908222-9d83-4c63-a857-5f6b396e9e6d"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. Text 1 states that Sykes felt Fletcher&rsquo;s contributions to the play were obvious because he had a distinct style in his other plays. Text 2 states that scholars generally agree &ldquo;on the basis of style&rdquo; that Fletcher wrote most of the three middle acts. Both texts imply that Fletcher&rsquo;s writing has a unique, readily identifiable style that can be used to distinguish his work from others. </p><p>Choice B is incorrect. While Text 1 refers to the women in Massinger plays, neither text compares the women of Fletcher&rsquo;s plays to the women of Massinger&rsquo;s plays. Text 2 doesn&rsquo;t mention Massinger at all. Choice C is incorrect. Text 1 states that Sykes disputed that Shakespeare coauthored the play, and implied that it was coauthored by Fletcher and Massinger instead. Sykes, therefore, would disagree that <em>The Two Noble Kinsmen</em> belongs in a Shakespeare compilation. Choice D is incorrect. Text 1 doesn&rsquo;t suggest that Massinger was inspired by Shakespeare, and Text 2 doesn&rsquo;t mention Massinger at all. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-H006$SATQ$, $SATQ$$SATQ$, $SATQ$d6cbf2b3-dc9b-4446-abd8-8e8cf8a97fbe$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"97e5bf55","external_id":"7a76d554-0375-4e2a-b0b2-5df72b2ce5b5","vaultid":"ee594b6b-07bc-478f-b2c8-f6d7be38051b","uId":"0a24026c-988b-405f-b326-20f0579a1fca","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><strong>Text 1</strong></p>\n<p>In 1916, H. Dugdale Sykes disputed claims that <em>The Two Noble Kinsmen</em> was coauthored by William Shakespeare and John Fletcher. Sykes felt Fletcher&rsquo;s contributions to the play were obvious&mdash;Fletcher had a distinct style in his other plays, so much so that lines with that style were considered sufficient evidence of Fletcher&rsquo;s authorship. But for the lines not deemed to be by Fletcher, Sykes felt that their depiction of women indicated that their author was not Shakespeare but Philip Massinger.</p>\n<p><strong>Text 2</strong></p>\n<p>Scholars have accepted <em>The Two Noble Kinsmen</em> as coauthored by Shakespeare since the 1970s: it appears in all major one-volume editions of Shakespeare&rsquo;s complete works. Though scholars disagree about who wrote what exactly, it is generally held that on the basis of style, Shakespeare wrote all of the first act and most of the last, while John Fletcher authored most of the three middle acts.</p>","stem":"<p>Based on the texts, both Sykes in Text 1 and the scholars in Text 2 would most likely agree with which statement?</p>","answerOptions":[{"id":"8f908222-9d83-4c63-a857-5f6b396e9e6d","content":"<p>John Fletcher&rsquo;s writing has a unique, readily identifiable style.</p>"},{"id":"c86d3827-3ab8-4586-a677-63e99e545a4c","content":"<p>The women characters in John Fletcher&rsquo;s plays are similar to the women characters in Philip Massinger&rsquo;s plays.</p>"},{"id":"ecfbfbb4-e49f-4901-a1a8-e6a3dbec8c14","content":"<p><em>The Two Noble Kinsmen</em> belongs in one-volume compilations of Shakespeare&rsquo;s complete plays.</p>"},{"id":"a934d487-6b03-4a3e-a380-4e10b227203f","content":"<p>Philip Massinger&rsquo;s style in the first and last acts of <em>The Two Noble Kinsmen</em> is an homage to Shakespeare&rsquo;s style.</p>"}],"keys":["8f908222-9d83-4c63-a857-5f6b396e9e6d"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. Text 1 states that Sykes felt Fletcher&rsquo;s contributions to the play were obvious because he had a distinct style in his other plays. Text 2 states that scholars generally agree &ldquo;on the basis of style&rdquo; that Fletcher wrote most of the three middle acts. Both texts imply that Fletcher&rsquo;s writing has a unique, readily identifiable style that can be used to distinguish his work from others. </p><p>Choice B is incorrect. While Text 1 refers to the women in Massinger plays, neither text compares the women of Fletcher&rsquo;s plays to the women of Massinger&rsquo;s plays. Text 2 doesn&rsquo;t mention Massinger at all. Choice C is incorrect. Text 1 states that Sykes disputed that Shakespeare coauthored the play, and implied that it was coauthored by Fletcher and Massinger instead. Sykes, therefore, would disagree that <em>The Two Noble Kinsmen</em> belongs in a Shakespeare compilation. Choice D is incorrect. Text 1 doesn&rsquo;t suggest that Massinger was inspired by Shakespeare, and Text 2 doesn&rsquo;t mention Massinger at all. </p>","parenttemplatename":"OSP-KA-CTC-H006","parenttemplateid":"","templateclusterid":"d6cbf2b3-dc9b-4446-abd8-8e8cf8a97fbe","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959365,"updateDate":1691007959365}$SATQ$::jsonb, 1691007959365, 1691007959365),
    ($SATQ$98364791$SATQ$, $SATQ$7c59600e-84ce-444a-a00b-274cf3423c3b$SATQ$::uuid, $SATQ$682b5d48-52bc-4fce-9382-0abc578fbf41$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In studying the use of external stimuli to reduce the itching sensation caused by an allergic histamine response, Louise Ward and colleagues found that while harmless applications of vibration or warming can provide a temporary distraction, such <span aria-hidden="true">______</span><span class="sr-only">blank</span> stimuli actually offer less relief than a stimulus that seems less benign, like a mild electric shock.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"494cac67-d240-49b6-bc31-1ddc3c66e81d","content":"<p>deceptive</p>"},{"id":"edc66f21-0674-4e89-8c83-36d70dee3171","content":"<p>innocuous</p>"},{"id":"14c972b4-a823-4c82-9207-5c7a71a2ae77","content":"<p>novel</p>"},{"id":"10818274-b52c-4141-b6bc-64808c4e1555","content":"<p>impractical</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["edc66f21-0674-4e89-8c83-36d70dee3171"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Ward and colleagues&rsquo; findings. As used in this context, &ldquo;innocuous&rdquo; means mild or unharmful. The text describes the vibration and warming that Ward and colleagues used to alleviate itching as &ldquo;harmless applications&rdquo; and goes on to contrast these applications with another stimulus that actually offers more relief even though it seems to be stronger and &ldquo;less benign.&rdquo; This context conveys the idea that vibration and warming were innocuous stimuli.&nbsp;</p><p>Choice A is incorrect because the text focuses on a distinction between harmless stimuli and those that seem to be less benign. Nothing in the text suggests that any of the treatments are &ldquo;deceptive,&rdquo; or misleading; indeed, even the less effective ones are described as offering some relief.&nbsp;Choice C is incorrect because the text focuses on the amount of relief from itching offered by harmless stimuli and those that seem to be less benign. The text doesn&rsquo;t suggest that any of these stimuli are &ldquo;novel,&rdquo; or original and new; heat, vibration, and electricity aren&rsquo;t new inventions. Choice D is incorrect because it wouldn&rsquo;t make sense to describe an application of vibration or warming as &ldquo;impractical,&rdquo; or not suitable for use. The text indicates that these harmless applications are useful in that they offer at least some temporary relief. </p>$SATQ$, false, 0, $SATQ$OSP-957-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$0db59e8b-a820-437e-8cdb-c713bf87b4de$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"98364791","external_id":"7c59600e-84ce-444a-a00b-274cf3423c3b","vaultid":"682b5d48-52bc-4fce-9382-0abc578fbf41","uId":"3a84b607-0d2c-48b7-b769-41f16138f8ba","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In studying the use of external stimuli to reduce the itching sensation caused by an allergic histamine response, Louise Ward and colleagues found that while harmless applications of vibration or warming can provide a temporary distraction, such <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> stimuli actually offer less relief than a stimulus that seems less benign, like a mild electric shock.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"494cac67-d240-49b6-bc31-1ddc3c66e81d","content":"<p>deceptive</p>"},{"id":"edc66f21-0674-4e89-8c83-36d70dee3171","content":"<p>innocuous</p>"},{"id":"14c972b4-a823-4c82-9207-5c7a71a2ae77","content":"<p>novel</p>"},{"id":"10818274-b52c-4141-b6bc-64808c4e1555","content":"<p>impractical</p>"}],"keys":["edc66f21-0674-4e89-8c83-36d70dee3171"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Ward and colleagues&rsquo; findings. As used in this context, &ldquo;innocuous&rdquo; means mild or unharmful. The text describes the vibration and warming that Ward and colleagues used to alleviate itching as &ldquo;harmless applications&rdquo; and goes on to contrast these applications with another stimulus that actually offers more relief even though it seems to be stronger and &ldquo;less benign.&rdquo; This context conveys the idea that vibration and warming were innocuous stimuli.&nbsp;</p><p>Choice A is incorrect because the text focuses on a distinction between harmless stimuli and those that seem to be less benign. Nothing in the text suggests that any of the treatments are &ldquo;deceptive,&rdquo; or misleading; indeed, even the less effective ones are described as offering some relief.&nbsp;Choice C is incorrect because the text focuses on the amount of relief from itching offered by harmless stimuli and those that seem to be less benign. The text doesn&rsquo;t suggest that any of these stimuli are &ldquo;novel,&rdquo; or original and new; heat, vibration, and electricity aren&rsquo;t new inventions. Choice D is incorrect because it wouldn&rsquo;t make sense to describe an application of vibration or warming as &ldquo;impractical,&rdquo; or not suitable for use. The text indicates that these harmless applications are useful in that they offer at least some temporary relief. </p>","parenttemplatename":"OSP-957-WIC","parenttemplateid":"","templateclusterid":"0db59e8b-a820-437e-8cdb-c713bf87b4de","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959357,"updateDate":1691007959357}$SATQ$::jsonb, 1691007959357, 1691007959357),
    ($SATQ$995358b4$SATQ$, $SATQ$9770f199-af07-4d33-97e9-37366cf8baa7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In a <span data-ssml-say-as="date">2022</span> study, Nicol&aacute;s <span data-ssml-sub-alias="M">M.</span> Morato and colleagues attempted to resolve a long-standing paradox: although water is critical to most reactions that enable life, during the earliest stages of Earth&rsquo;s history&mdash;when most of the planet&rsquo;s surface was covered by oceans&mdash;the presence of water likely <span aria-hidden="true">______</span><span class="sr-only">blank</span> the formation of proteins and other biomolecules that are found in all living organisms.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"ea08cc62-ee88-48cd-b573-a00fa951c27a","content":"<p>reflected</p>"},{"id":"fb6107bb-21e8-4dab-9012-2a19fcc37de1","content":"<p>hampered</p>"},{"id":"dc230b8f-85e9-4f95-a8a6-04b1bbac01c8","content":"<p>imitated</p>"},{"id":"e9914696-d752-47d4-9b43-00cc4de71f58","content":"<p>exploited</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["fb6107bb-21e8-4dab-9012-2a19fcc37de1"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of a scientific paradox regarding water and life during Earth&rsquo;s early history. In this context, &ldquo;hampered&rdquo; means hindered or impeded. The text discusses a paradox, or a situation that seems to contradict itself, and indicates that one half of the paradox is that the presence of water is necessary to support most biochemical reactions that enable life. The contradictory idea, then, would be a case of the presence of water not supporting such reactions; this context suggests that the other half of the paradox is that when oceans covered most of the planet, the water likely hindered or impeded a biochemical process (the formation of biomolecules) that is important for all living organisms.</p><p>Choice A is incorrect. In this context, &ldquo;reflected&rdquo; would mean showed or gave an indication. The text focuses on a paradox, or a seemingly self-contradictory situation, having to do with the role of water in supporting life; since the first part of the paradox has to do with water usually being essential for enabling life, the second part of the paradox should have to do with water having a negative effect on life, and water being an indication of a biomolecular process important for life wouldn&rsquo;t be a negative thing. Choice C is incorrect. In this context, &ldquo;imitated&rdquo; would mean mimicked or copied, and it isn&rsquo;t clear what it would mean to say that water being present on early Earth&rsquo;s surface somehow copied the creation of biomolecules in living organisms. Choice D is incorrect. In this context, &ldquo;exploited&rdquo; would mean used or took advantage of, and it isn&rsquo;t clear what it would mean to say that the presence of water&mdash;the fact of water being present&mdash;on early Earth&rsquo;s surface somehow took advantage of a biomolecular process occurring in living organisms.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"995358b4","external_id":"9770f199-af07-4d33-97e9-37366cf8baa7","vaultid":null,"uId":"840028ab-4ed4-47ca-bc47-dc1ce16b8d80","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In a <span data-ssml-say-as=\"date\">2022</span> study, Nicol&aacute;s <span data-ssml-sub-alias=\"M\">M.</span> Morato and colleagues attempted to resolve a long-standing paradox: although water is critical to most reactions that enable life, during the earliest stages of Earth&rsquo;s history&mdash;when most of the planet&rsquo;s surface was covered by oceans&mdash;the presence of water likely <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the formation of proteins and other biomolecules that are found in all living organisms.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"ea08cc62-ee88-48cd-b573-a00fa951c27a","content":"<p>reflected</p>"},{"id":"fb6107bb-21e8-4dab-9012-2a19fcc37de1","content":"<p>hampered</p>"},{"id":"dc230b8f-85e9-4f95-a8a6-04b1bbac01c8","content":"<p>imitated</p>"},{"id":"e9914696-d752-47d4-9b43-00cc4de71f58","content":"<p>exploited</p>"}],"keys":["fb6107bb-21e8-4dab-9012-2a19fcc37de1"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of a scientific paradox regarding water and life during Earth&rsquo;s early history. In this context, &ldquo;hampered&rdquo; means hindered or impeded. The text discusses a paradox, or a situation that seems to contradict itself, and indicates that one half of the paradox is that the presence of water is necessary to support most biochemical reactions that enable life. The contradictory idea, then, would be a case of the presence of water not supporting such reactions; this context suggests that the other half of the paradox is that when oceans covered most of the planet, the water likely hindered or impeded a biochemical process (the formation of biomolecules) that is important for all living organisms.</p><p>Choice A is incorrect. In this context, &ldquo;reflected&rdquo; would mean showed or gave an indication. The text focuses on a paradox, or a seemingly self-contradictory situation, having to do with the role of water in supporting life; since the first part of the paradox has to do with water usually being essential for enabling life, the second part of the paradox should have to do with water having a negative effect on life, and water being an indication of a biomolecular process important for life wouldn&rsquo;t be a negative thing. Choice C is incorrect. In this context, &ldquo;imitated&rdquo; would mean mimicked or copied, and it isn&rsquo;t clear what it would mean to say that water being present on early Earth&rsquo;s surface somehow copied the creation of biomolecules in living organisms. Choice D is incorrect. In this context, &ldquo;exploited&rdquo; would mean used or took advantage of, and it isn&rsquo;t clear what it would mean to say that the presence of water&mdash;the fact of water being present&mdash;on early Earth&rsquo;s surface somehow took advantage of a biomolecular process occurring in living organisms.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$9a94eb77$SATQ$, $SATQ$6fe7b031-d196-4dfd-a88d-f5e0b7402cc1$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 1</strong></span></p>
<p>One challenge faced by researchers studying global urbanization is that countries may define urban settlements differently. Many countries define urban settlements based on the number of people living in them. However, countries do not all use the same number; for example, Iceland uses a minimum population of 200, while the Netherlands uses 20,000. Other countries use a combination of population and other factors. This variation makes it difficult for researchers to compare aspects of urbanization in different countries.</p>
<p>&nbsp;</p>
<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 2</strong></span></p>
<p>Recently, a group of six international organizations developed global definitions of common types of settlements. The group developed a new measure called the &ldquo;degree of urbanization.&rdquo; This new measure establishes global criteria used to define three types of settlements (cities, towns, and rural areas) and allows researchers to better understand global urbanization rates.&nbsp;</p>
<p>&nbsp;</p>$SATQ$, $SATQ$<p>Based on the texts, how would the author of Text 2 most likely respond to the problem presented in Text 1?</p>$SATQ$, $SATQ$[{"id":"75c8bb0b-40a2-4f9c-adda-f479ad65056d","content":"<p>By recommending that a specific institution should further investigate the problem</p>"},{"id":"783813da-8315-43cf-b3d7-70dd462268df","content":"<p>By suggesting that researchers focus on topics besides urbanization</p>"},{"id":"bde00557-6248-453e-9fd4-d37f865a7920","content":"<p>By supplying additional ways in which urbanization research is difficult</p>"},{"id":"fe2371a2-a57d-4161-a7a8-1b7dec40822f","content":"<p>By noting that a possible solution to the problem is available</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["fe2371a2-a57d-4161-a7a8-1b7dec40822f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because Text 2 presents a possible solution to the problem identified in Text 1&mdash;that is, how disparities in the criteria used by different countries to define urban settlements make it "difficult for researchers to compare aspects of urbanization in different countries." Text 2 describes the creation of a shared framework for studying global urbanization: "global definitions of common types of settlements" and a "new measure called the &lsquo;degree of urbanization&rsquo;" that "allows researchers to better understand global urbanization rates."</p><p>Choice A is incorrect. Although Text 2 mentions "a group of six international organizations" that developed criteria and a measure related to settlements and urbanization, no organization or institution is singled out to perform further research. Choice B is incorrect because both texts are about urbanization research and neither mentions any other fields of study. Choice C is incorrect. Text 2 discusses a possible solution to the terminological problem in global urbanization research, not additional areas of difficulty in the field.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"9a94eb77","external_id":"6fe7b031-d196-4dfd-a88d-f5e0b7402cc1","vaultid":null,"uId":"976cdbf0-d2d0-4cad-9c90-972ed0db0f35","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 1</strong></span></p>\n<p>One challenge faced by researchers studying global urbanization is that countries may define urban settlements differently. Many countries define urban settlements based on the number of people living in them. However, countries do not all use the same number; for example, Iceland uses a minimum population of 200, while the Netherlands uses 20,000. Other countries use a combination of population and other factors. This variation makes it difficult for researchers to compare aspects of urbanization in different countries.</p>\n<p>&nbsp;</p>\n<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 2</strong></span></p>\n<p>Recently, a group of six international organizations developed global definitions of common types of settlements. The group developed a new measure called the &ldquo;degree of urbanization.&rdquo; This new measure establishes global criteria used to define three types of settlements (cities, towns, and rural areas) and allows researchers to better understand global urbanization rates.&nbsp;</p>\n<p>&nbsp;</p>","stem":"<p>Based on the texts, how would the author of Text 2 most likely respond to the problem presented in Text 1?</p>","answerOptions":[{"id":"75c8bb0b-40a2-4f9c-adda-f479ad65056d","content":"<p>By recommending that a specific institution should further investigate the problem</p>"},{"id":"783813da-8315-43cf-b3d7-70dd462268df","content":"<p>By suggesting that researchers focus on topics besides urbanization</p>"},{"id":"bde00557-6248-453e-9fd4-d37f865a7920","content":"<p>By supplying additional ways in which urbanization research is difficult</p>"},{"id":"fe2371a2-a57d-4161-a7a8-1b7dec40822f","content":"<p>By noting that a possible solution to the problem is available</p>"}],"keys":["fe2371a2-a57d-4161-a7a8-1b7dec40822f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because Text 2 presents a possible solution to the problem identified in Text 1&mdash;that is, how disparities in the criteria used by different countries to define urban settlements make it \"difficult for researchers to compare aspects of urbanization in different countries.\" Text 2 describes the creation of a shared framework for studying global urbanization: \"global definitions of common types of settlements\" and a \"new measure called the &lsquo;degree of urbanization&rsquo;\" that \"allows researchers to better understand global urbanization rates.\"</p><p>Choice A is incorrect. Although Text 2 mentions \"a group of six international organizations\" that developed criteria and a measure related to settlements and urbanization, no organization or institution is singled out to perform further research. Choice B is incorrect because both texts are about urbanization research and neither mentions any other fields of study. Choice C is incorrect. Text 2 discusses a possible solution to the terminological problem in global urbanization research, not additional areas of difficulty in the field.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061178,"updateDate":1755117061178}$SATQ$::jsonb, 1755117061178, 1755117061178),
    ($SATQ$9aa44886$SATQ$, $SATQ$01e38e21-9fcc-47d0-befd-d547fc90bc9c$SATQ$::uuid, $SATQ$16615aa8-04d9-4940-926e-398734a907c9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from F. Scott Fitzgerald&rsquo;s 1925 novel&nbsp;<em>The Great Gatsby</em>.</p>
<blockquote>
<p>[Jay Gatsby] was balancing himself on the dashboard of his car with that resourcefulness of movement that is so peculiarly American&mdash;that comes, I suppose, with the absence of lifting work in youth and, even more, with the formless grace of our nervous, sporadic games. This <span role="region" aria-label="Referenced Content"><u>quality</u></span> was continually breaking through his punctilious manner in the shape of restlessness.</p>
</blockquote>$SATQ$, $SATQ$<p>As used in the text, what does the word &ldquo;quality&rdquo; most nearly mean?</p>$SATQ$, $SATQ$[{"id":"3dfe9450-1e9c-4efd-85c7-3593b34997c2","content":"<p>Standard</p>"},{"id":"2de58e9e-9bda-48e4-9259-a209be071663","content":"<p>Prestige</p>"},{"id":"e550d111-e552-40ed-8c18-4dfe548bf8e9","content":"<p>Characteristic</p>"},{"id":"5b42fa61-4a89-49b6-8894-aefab541c722","content":"<p>Accomplishment</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["e550d111-e552-40ed-8c18-4dfe548bf8e9"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;This quality&rdquo; refers to Gatsby&rsquo;s &ldquo;resourcefulness of movement,&rdquo; which is described as a characteristic or trait of his.&nbsp;</p><p>Choice A is incorrect. This isn&rsquo;t what &ldquo;quality&rdquo; means in this context. Here, &ldquo;this quality&rdquo; refers to Gatsby&rsquo;s &ldquo;resourcefulness of movement,&rdquo; which is described as a characteristic or trait of his. &ldquo;Standard&rdquo; is a synonym for a different definition of &ldquo;quality&rdquo;: the degree of excellence of something.&nbsp;Choice B is incorrect. This isn&rsquo;t what &ldquo;quality&rdquo; means in this context. Here, &ldquo;this quality&rdquo; refers to Gatsby&rsquo;s &ldquo;resourcefulness of movement,&rdquo; which is described as a characteristic or trait of his. &ldquo;Prestige&rdquo; would suggest a high status or an admirable reputation, which doesn&rsquo;t match that description. Choice D is incorrect. This isn&rsquo;t what &ldquo;quality&rdquo; means in this context. Here, &ldquo;this quality&rdquo; refers to Gatsby&rsquo;s &ldquo;resourcefulness of movement,&rdquo; which is described as a characteristic or trait of his. &ldquo;Accomplishment&rdquo; would suggest an achievement, which doesn&rsquo;t match that description. &nbsp;&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-030-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$7caa8259-b6ae-45cf-96fe-814aa6f77232$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9aa44886","external_id":"01e38e21-9fcc-47d0-befd-d547fc90bc9c","vaultid":"16615aa8-04d9-4940-926e-398734a907c9","uId":"550f8089-1db2-423b-ac31-3ad4a132a321","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The following text is from F. Scott Fitzgerald&rsquo;s 1925 novel&nbsp;<em>The Great Gatsby</em>.</p>\n<blockquote>\n<p>[Jay Gatsby] was balancing himself on the dashboard of his car with that resourcefulness of movement that is so peculiarly American&mdash;that comes, I suppose, with the absence of lifting work in youth and, even more, with the formless grace of our nervous, sporadic games. This <span role=\"region\" aria-label=\"Referenced Content\"><u>quality</u></span> was continually breaking through his punctilious manner in the shape of restlessness.</p>\n</blockquote>","stem":"<p>As used in the text, what does the word &ldquo;quality&rdquo; most nearly mean?</p>","answerOptions":[{"id":"3dfe9450-1e9c-4efd-85c7-3593b34997c2","content":"<p>Standard</p>"},{"id":"2de58e9e-9bda-48e4-9259-a209be071663","content":"<p>Prestige</p>"},{"id":"e550d111-e552-40ed-8c18-4dfe548bf8e9","content":"<p>Characteristic</p>"},{"id":"5b42fa61-4a89-49b6-8894-aefab541c722","content":"<p>Accomplishment</p>"}],"keys":["e550d111-e552-40ed-8c18-4dfe548bf8e9"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;This quality&rdquo; refers to Gatsby&rsquo;s &ldquo;resourcefulness of movement,&rdquo; which is described as a characteristic or trait of his.&nbsp;</p><p>Choice A is incorrect. This isn&rsquo;t what &ldquo;quality&rdquo; means in this context. Here, &ldquo;this quality&rdquo; refers to Gatsby&rsquo;s &ldquo;resourcefulness of movement,&rdquo; which is described as a characteristic or trait of his. &ldquo;Standard&rdquo; is a synonym for a different definition of &ldquo;quality&rdquo;: the degree of excellence of something.&nbsp;Choice B is incorrect. This isn&rsquo;t what &ldquo;quality&rdquo; means in this context. Here, &ldquo;this quality&rdquo; refers to Gatsby&rsquo;s &ldquo;resourcefulness of movement,&rdquo; which is described as a characteristic or trait of his. &ldquo;Prestige&rdquo; would suggest a high status or an admirable reputation, which doesn&rsquo;t match that description. Choice D is incorrect. This isn&rsquo;t what &ldquo;quality&rdquo; means in this context. Here, &ldquo;this quality&rdquo; refers to Gatsby&rsquo;s &ldquo;resourcefulness of movement,&rdquo; which is described as a characteristic or trait of his. &ldquo;Accomplishment&rdquo; would suggest an achievement, which doesn&rsquo;t match that description. &nbsp;&nbsp;</p>","parenttemplatename":"OSP-030-WIC","parenttemplateid":"","templateclusterid":"7caa8259-b6ae-45cf-96fe-814aa6f77232","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959319,"updateDate":1691007959319}$SATQ$::jsonb, 1691007959319, 1691007959319),
    ($SATQ$9b01bcf4$SATQ$, $SATQ$b7a610b9-e72a-43ef-a2e5-5e1f3fb001e5$SATQ$::uuid, $SATQ$516cda05-bd34-47f7-aee1-1da58c9844b0$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The 1967 release of Harold Cruse&rsquo;s book <em>The Crisis of the Negro Intellectual </em>isolated him from almost all other scholars and activists of the American Civil Rights Movement&mdash;though many of those thinkers disagreed with each other, he nonetheless found ways to disagree with them all. He thought that activists who believed that Black people such as himself should culturally assimilate were na&iuml;ve. <span role="region" aria-label="Referenced Content"><u>But he also sharply criticized Black nationalists such as Marcus Garvey who wanted to establish independent, self-contained Black economies and societies, even though Cruse himself identified as a Black nationalist.</u></span></p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"bb7971e1-5b9e-464b-b1e4-004bd9cc48bc","content":"<p>It describes a direction that Cruse felt the Civil Rights Movement ought to take.</p>"},{"id":"82049269-1b08-411c-91f7-f7b7dc706094","content":"<p>It indicates that Cruse&rsquo;s reputation as a persistent antagonist of other scholars is undeserved.</p>"},{"id":"027b2111-1dbf-4496-9c3d-2709bd8995a8","content":"<p>It describes a controversy that Cruse&rsquo;s work caused within the Black nationalist movement.</p>"},{"id":"c6f0b315-6d47-4df1-a4cd-61040e25ae4b","content":"<p>It helps explain Cruse&rsquo;s position with respect to the community of civil rights thinkers.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["c6f0b315-6d47-4df1-a4cd-61040e25ae4b"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The text as a whole claims that Cruse disagreed with virtually all other Civil Rights scholars and activists. The underlined sentence describes one way that Cruse both did and didn&rsquo;t fit in with those thinkers: he criticized Black nationalists, even though he identified as one. </p><p>Choice A is incorrect. The underlined sentence doesn&rsquo;t do this. It describes Cruse&rsquo;s criticisms&mdash;it never mentions what Cruse did want the movement to do instead. Choice B is incorrect. This conflicts with the text, which argues that Cruse did disagree with almost all other scholars of the Civil Rights Movement. Choice C is incorrect. This is a step too far. The text never says that Cruse&rsquo;s work caused controversy within the Black nationalist movement. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-H003$SATQ$, $SATQ$$SATQ$, $SATQ$8d84ea33-57f6-42f5-92ec-6082766264c9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9b01bcf4","external_id":"b7a610b9-e72a-43ef-a2e5-5e1f3fb001e5","vaultid":"516cda05-bd34-47f7-aee1-1da58c9844b0","uId":"fb51949d-6200-410a-ae7b-8a3bbacbe9a1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The 1967 release of Harold Cruse&rsquo;s book <em>The Crisis of the Negro Intellectual </em>isolated him from almost all other scholars and activists of the American Civil Rights Movement&mdash;though many of those thinkers disagreed with each other, he nonetheless found ways to disagree with them all. He thought that activists who believed that Black people such as himself should culturally assimilate were na&iuml;ve. <span role=\"region\" aria-label=\"Referenced Content\"><u>But he also sharply criticized Black nationalists such as Marcus Garvey who wanted to establish independent, self-contained Black economies and societies, even though Cruse himself identified as a Black nationalist.</u></span></p>","stem":"<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>","answerOptions":[{"id":"bb7971e1-5b9e-464b-b1e4-004bd9cc48bc","content":"<p>It describes a direction that Cruse felt the Civil Rights Movement ought to take.</p>"},{"id":"82049269-1b08-411c-91f7-f7b7dc706094","content":"<p>It indicates that Cruse&rsquo;s reputation as a persistent antagonist of other scholars is undeserved.</p>"},{"id":"027b2111-1dbf-4496-9c3d-2709bd8995a8","content":"<p>It describes a controversy that Cruse&rsquo;s work caused within the Black nationalist movement.</p>"},{"id":"c6f0b315-6d47-4df1-a4cd-61040e25ae4b","content":"<p>It helps explain Cruse&rsquo;s position with respect to the community of civil rights thinkers.</p>"}],"keys":["c6f0b315-6d47-4df1-a4cd-61040e25ae4b"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The text as a whole claims that Cruse disagreed with virtually all other Civil Rights scholars and activists. The underlined sentence describes one way that Cruse both did and didn&rsquo;t fit in with those thinkers: he criticized Black nationalists, even though he identified as one. </p><p>Choice A is incorrect. The underlined sentence doesn&rsquo;t do this. It describes Cruse&rsquo;s criticisms&mdash;it never mentions what Cruse did want the movement to do instead. Choice B is incorrect. This conflicts with the text, which argues that Cruse did disagree with almost all other scholars of the Civil Rights Movement. Choice C is incorrect. This is a step too far. The text never says that Cruse&rsquo;s work caused controversy within the Black nationalist movement. </p>","parenttemplatename":"OSP-KA-TSP-H003","parenttemplateid":"","templateclusterid":"8d84ea33-57f6-42f5-92ec-6082766264c9","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959375,"updateDate":1691007959375}$SATQ$::jsonb, 1691007959375, 1691007959375),
    ($SATQ$9b22bf7b$SATQ$, $SATQ$6580ca6a-cfd2-4b81-8c28-03ae9d76318f$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from the 1989 novel <em>The Ancient Child</em> by Kiowa writer N. Scott Momaday. The main character has achieved tremendous commercial success as a painter.</p>
<blockquote>
<p>More and more often he was asked to compromise his art or himself in one way or another, and more often than not he did so, for he was inclined to be passive and na&iuml;ve; it was difficult for him to say no. Those who exhibited his work, who praised and purchased it, and who demanded its proliferation began to <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">determine</span> it.</p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;1989 by N. Scott Momaday</span></p>$SATQ$, $SATQ$<p>As used in the text, what does the word &ldquo;determine&rdquo; most nearly mean?</p>$SATQ$, $SATQ$[{"id":"f1ee04af-c6af-4620-9301-c3d715d039a1","content":"<p>Conclude</p>"},{"id":"751b6c8b-a79c-4999-b04b-fa5a5a693659","content":"<p>Dictate</p>"},{"id":"187f3a71-42f2-480e-b036-de68bfece448","content":"<p>Evaluate</p>"},{"id":"cb033321-362f-4cc1-a8ee-eec52d0a48f4","content":"<p>Select</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["751b6c8b-a79c-4999-b04b-fa5a5a693659"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because as used in the text "determine" most nearly means "dictate." The text describes the relationship between the main character and those who exhibit, praise, and purchase his artwork. The text states that the main character is often asked to change his art or himself based on outside influences, and he usually acquiesces. Because the main character admits that those who support his work often shape it based on their demands, it follows that those outside influences dictate, or guide or dominate, the direction his work takes.</p><p>Choice A is incorrect because the text doesn&rsquo;t suggest that outside influences "conclude," or end, the main character&rsquo;s work. The text states that many supporters of the main character&rsquo;s art "demand its proliferation," not its conclusion. Choice C is incorrect because the text doesn&rsquo;t suggest that outside influences are "evaluating," or judging the main character&rsquo;s work. According to the text, the main character&rsquo;s art has already achieved great commercial success, with many people exhibiting, purchasing, and praising his work. Thus, outsiders have already supported the main character&rsquo;s work and are not questioning or evaluating its success or worth. They are instead influencing its initial direction. Choice D is incorrect because the text doesn&rsquo;t suggest that outside influences "select," or choose the main character&rsquo;s work. According to the text, the main character&rsquo;s art has already achieved great commercial success, with many people exhibiting, purchasing, and praising his work. Thus, outsiders have already supported the main character&rsquo;s work and are not selecting it. They are instead influencing its initial direction.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"9b22bf7b","external_id":"6580ca6a-cfd2-4b81-8c28-03ae9d76318f","vaultid":null,"uId":"583775f8-8097-4694-8535-f555c0d97192","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The following text is from the 1989 novel <em>The Ancient Child</em> by Kiowa writer N. Scott Momaday. The main character has achieved tremendous commercial success as a painter.</p>\n<blockquote>\n<p>More and more often he was asked to compromise his art or himself in one way or another, and more often than not he did so, for he was inclined to be passive and na&iuml;ve; it was difficult for him to say no. Those who exhibited his work, who praised and purchased it, and who demanded its proliferation began to <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">determine</span> it.</p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;1989 by N. Scott Momaday</span></p>","stem":"<p>As used in the text, what does the word &ldquo;determine&rdquo; most nearly mean?</p>","answerOptions":[{"id":"f1ee04af-c6af-4620-9301-c3d715d039a1","content":"<p>Conclude</p>"},{"id":"751b6c8b-a79c-4999-b04b-fa5a5a693659","content":"<p>Dictate</p>"},{"id":"187f3a71-42f2-480e-b036-de68bfece448","content":"<p>Evaluate</p>"},{"id":"cb033321-362f-4cc1-a8ee-eec52d0a48f4","content":"<p>Select</p>"}],"keys":["751b6c8b-a79c-4999-b04b-fa5a5a693659"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because as used in the text \"determine\" most nearly means \"dictate.\" The text describes the relationship between the main character and those who exhibit, praise, and purchase his artwork. The text states that the main character is often asked to change his art or himself based on outside influences, and he usually acquiesces. Because the main character admits that those who support his work often shape it based on their demands, it follows that those outside influences dictate, or guide or dominate, the direction his work takes.</p><p>Choice A is incorrect because the text doesn&rsquo;t suggest that outside influences \"conclude,\" or end, the main character&rsquo;s work. The text states that many supporters of the main character&rsquo;s art \"demand its proliferation,\" not its conclusion. Choice C is incorrect because the text doesn&rsquo;t suggest that outside influences are \"evaluating,\" or judging the main character&rsquo;s work. According to the text, the main character&rsquo;s art has already achieved great commercial success, with many people exhibiting, purchasing, and praising his work. Thus, outsiders have already supported the main character&rsquo;s work and are not questioning or evaluating its success or worth. They are instead influencing its initial direction. Choice D is incorrect because the text doesn&rsquo;t suggest that outside influences \"select,\" or choose the main character&rsquo;s work. According to the text, the main character&rsquo;s art has already achieved great commercial success, with many people exhibiting, purchasing, and praising his work. Thus, outsiders have already supported the main character&rsquo;s work and are not selecting it. They are instead influencing its initial direction.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323052,"updateDate":1730147323052}$SATQ$::jsonb, 1730147323052, 1730147323052),
    ($SATQ$9b2fbb2e$SATQ$, $SATQ$73093381-38f2-46fd-9909-0a8c60323450$SATQ$::uuid, $SATQ$ac3bac6c-e6a7-43ab-a36e-60a0bb257366$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Logically, a damaged fossil should provide less information than an intact one, but for paleontologist Brigitte Schoenemann, a broken area on a fossilized trilobite (a crustacean-like creature) <span aria-hidden="true">______</span><span class="sr-only">blank</span> fresh insight, allowing her to view the inner structure of the organism&rsquo;s eye.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"1078e5f9-ac5f-4f4e-851e-ecb3947f8718","content":"<p>resolved</p>"},{"id":"495043af-b476-4899-8b4d-effd241d8053","content":"<p>adjusted</p>"},{"id":"ad80726a-2b5a-4250-a4d1-51e30e0cbf0e","content":"<p>offered</p>"},{"id":"49d14186-0703-468b-af22-72e9c4b1eae9","content":"<p>directed</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["ad80726a-2b5a-4250-a4d1-51e30e0cbf0e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion about how, for Schoenemann, a damaged trilobite fossil was informative. In context, &ldquo;offered&rdquo; means provided or gave. The text suggests that although it may seem counterintuitive, a broken fossilized trilobite allowed Schoenemann to observe more details of the trilobite&rsquo;s eye than an intact fossilized trilobite would. This context conveys the idea that a damaged fossil offered, or provided, fresh insight into the structure of a trilobite&rsquo;s eye. </p><p>Choice A is incorrect&nbsp;because &ldquo;resolved&rdquo; means determined or figured out, which wouldn&rsquo;t make sense in this context. The text focuses on how Schoenemann was able to get more information from a broken fossil than an intact one. Although the damaged fossil may have allowed her to determine certain information, as an inanimate object the fossil isn&rsquo;t capable of resolving anything. Choice B is incorrect because saying that the broken part of a trilobite fossil &ldquo;adjusted,&rdquo; or changed or modified, fresh insight wouldn&rsquo;t make sense in this context. The text focuses on how Schoenemann was able to get more information from a broken fossil than an intact one. This context suggests that the fossil offered fresh insight, or understanding, not that it adjusted fresh insight.&nbsp;Choice D is incorrect because &ldquo;directed&rdquo; means managed or instructed, which wouldn&rsquo;t make sense in this context. The text focuses on how Schoenemann was able to get more information from a broken fossil than an intact one. This context suggests that the fossil offered fresh insight, or understanding, not that it directed fresh insight. </p>$SATQ$, false, 0, $SATQ$OSP-958-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$a79a3d5c-00d2-46f1-8b71-72b78bb71fe0$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9b2fbb2e","external_id":"73093381-38f2-46fd-9909-0a8c60323450","vaultid":"ac3bac6c-e6a7-43ab-a36e-60a0bb257366","uId":"cbd2d73e-ba7e-4275-b9d4-e41de7752d3a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Logically, a damaged fossil should provide less information than an intact one, but for paleontologist Brigitte Schoenemann, a broken area on a fossilized trilobite (a crustacean-like creature) <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> fresh insight, allowing her to view the inner structure of the organism&rsquo;s eye.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"1078e5f9-ac5f-4f4e-851e-ecb3947f8718","content":"<p>resolved</p>"},{"id":"495043af-b476-4899-8b4d-effd241d8053","content":"<p>adjusted</p>"},{"id":"ad80726a-2b5a-4250-a4d1-51e30e0cbf0e","content":"<p>offered</p>"},{"id":"49d14186-0703-468b-af22-72e9c4b1eae9","content":"<p>directed</p>"}],"keys":["ad80726a-2b5a-4250-a4d1-51e30e0cbf0e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion about how, for Schoenemann, a damaged trilobite fossil was informative. In context, &ldquo;offered&rdquo; means provided or gave. The text suggests that although it may seem counterintuitive, a broken fossilized trilobite allowed Schoenemann to observe more details of the trilobite&rsquo;s eye than an intact fossilized trilobite would. This context conveys the idea that a damaged fossil offered, or provided, fresh insight into the structure of a trilobite&rsquo;s eye. </p><p>Choice A is incorrect&nbsp;because &ldquo;resolved&rdquo; means determined or figured out, which wouldn&rsquo;t make sense in this context. The text focuses on how Schoenemann was able to get more information from a broken fossil than an intact one. Although the damaged fossil may have allowed her to determine certain information, as an inanimate object the fossil isn&rsquo;t capable of resolving anything. Choice B is incorrect because saying that the broken part of a trilobite fossil &ldquo;adjusted,&rdquo; or changed or modified, fresh insight wouldn&rsquo;t make sense in this context. The text focuses on how Schoenemann was able to get more information from a broken fossil than an intact one. This context suggests that the fossil offered fresh insight, or understanding, not that it adjusted fresh insight.&nbsp;Choice D is incorrect because &ldquo;directed&rdquo; means managed or instructed, which wouldn&rsquo;t make sense in this context. The text focuses on how Schoenemann was able to get more information from a broken fossil than an intact one. This context suggests that the fossil offered fresh insight, or understanding, not that it directed fresh insight. </p>","parenttemplatename":"OSP-958-WIC","parenttemplateid":"","templateclusterid":"a79a3d5c-00d2-46f1-8b71-72b78bb71fe0","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959357,"updateDate":1691007959357}$SATQ$::jsonb, 1691007959357, 1691007959357),
    ($SATQ$9c35759f$SATQ$, $SATQ$258b2444-8a77-48d5-8e99-8e9789fe6ccd$SATQ$::uuid, $SATQ$6a7fa3cb-1180-4ce3-9ebd-aa0a804d6c38$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Novelist N. K. Jemisin declines to <span aria-hidden="true">______</span><span class="sr-only">blank</span> the conventions of the science fiction genre in which she writes, and she has suggested that her readers appreciate her work precisely because of this willingness to thwart expectations and avoid formulaic plots and themes.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"53dd1555-07bb-4a21-8dbf-5ebd196605a4","content":"<p>question</p>"},{"id":"e695a9bb-9093-435d-a223-6bfed5ad8278","content":"<p>react to</p>"},{"id":"45cb14d3-7c22-4e94-83a8-6939fc41a4f2","content":"<p>perceive</p>"},{"id":"d240b528-93fb-401e-997c-826062032b6b","content":"<p>conform to</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["d240b528-93fb-401e-997c-826062032b6b"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of Jemisin&rsquo;s writing. In this context, &ldquo;conform to&rdquo; means to act in accordance with something. The text suggests that in her science fiction writing, Jemisin&rsquo;s willingness to go against expectations and not use plots and themes that seem to follow a formula reflects how she treats the standard practices of the genre. This context conveys that Jemisin chooses not to act in accordance with those conventions. </p><p>Choice A is incorrect. In this context, &ldquo;question&rdquo; would mean doubt or object to. The text indicates that Jemisin is willing to go against expectations and not use formulaic plots and themes in her science fiction writing, suggesting that she may actually object to those conventions of the genre, not that she chooses not to question them.&nbsp;Choice B is incorrect because the text indicates that in her science fiction writing, Jemisin is willing to go against expectations and not use formulaic plots and themes. Rather than suggesting that Jemisin chooses not to &ldquo;react to,&rdquo; or act in response to, the standard practices of the genre, this context suggests that she is acting in response to such conventions by deliberately avoiding them. Choice C is incorrect. In this context, &ldquo;perceive&rdquo; would mean become aware of or understand. The text indicates that in her science fiction writing, Jemisin is willing to go against expectations and not use formulaic plots and themes. This context conveys that Jemisin is aware of and deliberately avoids those conventions of the genre, not that she chooses not to be aware of them. </p>$SATQ$, false, 0, $SATQ$OSP-928-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$92acce12-bf8f-436f-b043-985ebceada27$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9c35759f","external_id":"258b2444-8a77-48d5-8e99-8e9789fe6ccd","vaultid":"6a7fa3cb-1180-4ce3-9ebd-aa0a804d6c38","uId":"d6b28002-5980-45c1-a5ac-d41671009196","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Novelist N. K. Jemisin declines to <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the conventions of the science fiction genre in which she writes, and she has suggested that her readers appreciate her work precisely because of this willingness to thwart expectations and avoid formulaic plots and themes.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"53dd1555-07bb-4a21-8dbf-5ebd196605a4","content":"<p>question</p>"},{"id":"e695a9bb-9093-435d-a223-6bfed5ad8278","content":"<p>react to</p>"},{"id":"45cb14d3-7c22-4e94-83a8-6939fc41a4f2","content":"<p>perceive</p>"},{"id":"d240b528-93fb-401e-997c-826062032b6b","content":"<p>conform to</p>"}],"keys":["d240b528-93fb-401e-997c-826062032b6b"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of Jemisin&rsquo;s writing. In this context, &ldquo;conform to&rdquo; means to act in accordance with something. The text suggests that in her science fiction writing, Jemisin&rsquo;s willingness to go against expectations and not use plots and themes that seem to follow a formula reflects how she treats the standard practices of the genre. This context conveys that Jemisin chooses not to act in accordance with those conventions. </p><p>Choice A is incorrect. In this context, &ldquo;question&rdquo; would mean doubt or object to. The text indicates that Jemisin is willing to go against expectations and not use formulaic plots and themes in her science fiction writing, suggesting that she may actually object to those conventions of the genre, not that she chooses not to question them.&nbsp;Choice B is incorrect because the text indicates that in her science fiction writing, Jemisin is willing to go against expectations and not use formulaic plots and themes. Rather than suggesting that Jemisin chooses not to &ldquo;react to,&rdquo; or act in response to, the standard practices of the genre, this context suggests that she is acting in response to such conventions by deliberately avoiding them. Choice C is incorrect. In this context, &ldquo;perceive&rdquo; would mean become aware of or understand. The text indicates that in her science fiction writing, Jemisin is willing to go against expectations and not use formulaic plots and themes. This context conveys that Jemisin is aware of and deliberately avoids those conventions of the genre, not that she chooses not to be aware of them. </p>","parenttemplatename":"OSP-928-WIC","parenttemplateid":"","templateclusterid":"92acce12-bf8f-436f-b043-985ebceada27","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959356,"updateDate":1691007959356}$SATQ$::jsonb, 1691007959356, 1691007959356),
    ($SATQ$9c759a09$SATQ$, $SATQ$926776f3-b17f-41a4-a3d2-ec4626de0ab5$SATQ$::uuid, $SATQ$2e2724f5-d95b-487b-9f09-6b5531f39542$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Georgia Douglas Johnson&rsquo;s 1922 poem &ldquo;Benediction.&rdquo;</p>
<p style="padding-left:1em;">Go forth, my son,<br>Winged by my heart&rsquo;s desire!<br>Great reaches, yet unknown,<br>Await<br>For your possession.<br>I may not, if I would,<br>Retrace the way with you,<br>My pilgrimage is through,<br>But life is calling you!</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text? </p>$SATQ$, $SATQ$[{"id":"a4557f17-dc85-4515-8d03-d75ae883ff0c","content":"<p>To express hope that a child will have the same accomplishments as his parent did</p>"},{"id":"6a488771-3b35-414f-bb91-bba8077aa27c","content":"<p>To suggest that raising a child involves many struggles</p>"},{"id":"5385d1fe-4210-4b8e-9aa7-53864f0299cc","content":"<p>To warn a child that he will face many challenges throughout his life</p>"},{"id":"7b65c0f8-b042-4898-bc46-fbdfc9dd534c","content":"<p>To encourage a child to embrace the experiences life will offer</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["7b65c0f8-b042-4898-bc46-fbdfc9dd534c"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it accurately states the text&rsquo;s main purpose. The poem begins with the speaker urging a child to &ldquo;go forth&rdquo; with her encouragement (&ldquo;my heart&rsquo;s desire&rdquo;). The speaker goes on to suggest that new experiences (&ldquo;Great reaches, yet unknown&rdquo;) lie ahead for the son that &ldquo;life is calling&rdquo; him to seek out. Thus, the main purpose is to encourage a child to embrace the experiences available to him in his life. </p><p>Choice A is incorrect because the speaker encourages the child to pursue new experiences (&ldquo;Great reaches&rdquo;) without knowing exactly what those experiences will be (&ldquo;yet unknown&rdquo;) or suggesting that they should match the speaker&rsquo;s own accomplishments. Choice B is incorrect because the speaker focuses on positive possibilities for her son (&ldquo;Great reaches, yet unknown&rdquo;) and her enthusiastic encouragement to embrace those possibilities (&ldquo;life is calling you!&rdquo;), while there is no mention of raising a child or associated struggles. Choice C is incorrect because the speaker frames the possibilities for her son in a positive light when she says that &ldquo;great reaches, yet unknown&rdquo; are waiting for him, and this positive outlook for the son is consistent throughout the text. </p>$SATQ$, false, 0, $SATQ$OSP-020-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$da68c905-3997-478f-995e-b5cb45d759e6$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9c759a09","external_id":"926776f3-b17f-41a4-a3d2-ec4626de0ab5","vaultid":"2e2724f5-d95b-487b-9f09-6b5531f39542","uId":"72ddbf87-a223-4eca-82cb-507e95e7ec29","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is from Georgia Douglas Johnson&rsquo;s 1922 poem &ldquo;Benediction.&rdquo;</p>\n<p style=\"padding-left:1em;\">Go forth, my son,<br>Winged by my heart&rsquo;s desire!<br>Great reaches, yet unknown,<br>Await<br>For your possession.<br>I may not, if I would,<br>Retrace the way with you,<br>My pilgrimage is through,<br>But life is calling you!</p>","stem":"<p>Which choice best states the main purpose of the text? </p>","answerOptions":[{"id":"a4557f17-dc85-4515-8d03-d75ae883ff0c","content":"<p>To express hope that a child will have the same accomplishments as his parent did</p>"},{"id":"6a488771-3b35-414f-bb91-bba8077aa27c","content":"<p>To suggest that raising a child involves many struggles</p>"},{"id":"5385d1fe-4210-4b8e-9aa7-53864f0299cc","content":"<p>To warn a child that he will face many challenges throughout his life</p>"},{"id":"7b65c0f8-b042-4898-bc46-fbdfc9dd534c","content":"<p>To encourage a child to embrace the experiences life will offer</p>"}],"keys":["7b65c0f8-b042-4898-bc46-fbdfc9dd534c"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it accurately states the text&rsquo;s main purpose. The poem begins with the speaker urging a child to &ldquo;go forth&rdquo; with her encouragement (&ldquo;my heart&rsquo;s desire&rdquo;). The speaker goes on to suggest that new experiences (&ldquo;Great reaches, yet unknown&rdquo;) lie ahead for the son that &ldquo;life is calling&rdquo; him to seek out. Thus, the main purpose is to encourage a child to embrace the experiences available to him in his life. </p><p>Choice A is incorrect because the speaker encourages the child to pursue new experiences (&ldquo;Great reaches&rdquo;) without knowing exactly what those experiences will be (&ldquo;yet unknown&rdquo;) or suggesting that they should match the speaker&rsquo;s own accomplishments. Choice B is incorrect because the speaker focuses on positive possibilities for her son (&ldquo;Great reaches, yet unknown&rdquo;) and her enthusiastic encouragement to embrace those possibilities (&ldquo;life is calling you!&rdquo;), while there is no mention of raising a child or associated struggles. Choice C is incorrect because the speaker frames the possibilities for her son in a positive light when she says that &ldquo;great reaches, yet unknown&rdquo; are waiting for him, and this positive outlook for the son is consistent throughout the text. </p>","parenttemplatename":"OSP-020-TSP","parenttemplateid":"","templateclusterid":"da68c905-3997-478f-995e-b5cb45d759e6","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959317,"updateDate":1691007959317}$SATQ$::jsonb, 1691007959317, 1691007959317),
    ($SATQ$9ccf463e$SATQ$, $SATQ$34595d00-e2e3-49d2-9ab1-7f222dc78786$SATQ$::uuid, $SATQ$8697001d-2b48-4422-92a3-39a09ab921b4$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Nella Larsen&rsquo;s 1928 novel <em>Quicksand</em>.</p>
<blockquote>
<p>The trees in their spring beauty sent through her restive mind a sharp thrill of pleasure. Seductive, charming, and <span role="region" aria-label="Referenced Content"><u>beckoning</u></span> as cities were, they had not this easy unhuman loveliness.</p>
</blockquote>$SATQ$, $SATQ$<p>As used in the text, what does the word &ldquo;beckoning&rdquo; most nearly mean?</p>$SATQ$, $SATQ$[{"id":"00456315-95a2-442b-8bbb-8fbed9ac878c","content":"<p>Demanding</p>"},{"id":"a41f8ce8-2dd5-47db-abf0-e5ab27985cdb","content":"<p>Signaling</p>"},{"id":"86766cc2-4bfe-42e9-941e-6ef3af823c89","content":"<p>Inviting</p>"},{"id":"5e960db5-6fb7-4033-8003-3209a02b301b","content":"<p>Shifting</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["86766cc2-4bfe-42e9-941e-6ef3af823c89"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because as used in the text, &ldquo;beckoning&rdquo; most nearly means &ldquo;inviting,&rdquo; or attractive. The text portrays a woman who is looking at &ldquo;trees in their spring beauty.&rdquo; She compares them to cities, which have their own pleasures even if they do not have the &ldquo;easy unhuman loveliness&rdquo; of trees: she thinks of cities as &ldquo;seductive&rdquo; and &ldquo;charming,&rdquo; both adjectives that signify something that is enticing, or attractive. Therefore, cities that are seductive and charming would also be described as inviting people closer to them. </p><p>Choice A is incorrect because there is no indication in this context that cities are &ldquo;demanding,&rdquo; or requiring effort. Choice B is incorrect. Though &ldquo;signaling,&rdquo; or communicating something, might be considered a key feature of the act of &ldquo;beckoning,&rdquo; in the context here, &ldquo;beckoning&rdquo; suggests that cities have attractive qualities that naturally draw people to them. Such attractive qualities are not described by the word &ldquo;signaling&rdquo; alone. Therefore, &ldquo;signaling&rdquo; is an incorrect answer because it is insufficiently precise. Choice D is incorrect because there is no reason to think in this context that the cities are &ldquo;shifting,&rdquo; or changing shape. </p>$SATQ$, false, 0, $SATQ$OSP-008-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$cc0f5905-c9cb-4eb5-9322-da8f0e0094cb$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9ccf463e","external_id":"34595d00-e2e3-49d2-9ab1-7f222dc78786","vaultid":"8697001d-2b48-4422-92a3-39a09ab921b4","uId":"26eeea6d-a6b5-40f0-b2c1-cbfc3eaa1600","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The following text is from Nella Larsen&rsquo;s 1928 novel <em>Quicksand</em>.</p>\n<blockquote>\n<p>The trees in their spring beauty sent through her restive mind a sharp thrill of pleasure. Seductive, charming, and <span role=\"region\" aria-label=\"Referenced Content\"><u>beckoning</u></span> as cities were, they had not this easy unhuman loveliness.</p>\n</blockquote>","stem":"<p>As used in the text, what does the word &ldquo;beckoning&rdquo; most nearly mean?</p>","answerOptions":[{"id":"00456315-95a2-442b-8bbb-8fbed9ac878c","content":"<p>Demanding</p>"},{"id":"a41f8ce8-2dd5-47db-abf0-e5ab27985cdb","content":"<p>Signaling</p>"},{"id":"86766cc2-4bfe-42e9-941e-6ef3af823c89","content":"<p>Inviting</p>"},{"id":"5e960db5-6fb7-4033-8003-3209a02b301b","content":"<p>Shifting</p>"}],"keys":["86766cc2-4bfe-42e9-941e-6ef3af823c89"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because as used in the text, &ldquo;beckoning&rdquo; most nearly means &ldquo;inviting,&rdquo; or attractive. The text portrays a woman who is looking at &ldquo;trees in their spring beauty.&rdquo; She compares them to cities, which have their own pleasures even if they do not have the &ldquo;easy unhuman loveliness&rdquo; of trees: she thinks of cities as &ldquo;seductive&rdquo; and &ldquo;charming,&rdquo; both adjectives that signify something that is enticing, or attractive. Therefore, cities that are seductive and charming would also be described as inviting people closer to them. </p><p>Choice A is incorrect because there is no indication in this context that cities are &ldquo;demanding,&rdquo; or requiring effort. Choice B is incorrect. Though &ldquo;signaling,&rdquo; or communicating something, might be considered a key feature of the act of &ldquo;beckoning,&rdquo; in the context here, &ldquo;beckoning&rdquo; suggests that cities have attractive qualities that naturally draw people to them. Such attractive qualities are not described by the word &ldquo;signaling&rdquo; alone. Therefore, &ldquo;signaling&rdquo; is an incorrect answer because it is insufficiently precise. Choice D is incorrect because there is no reason to think in this context that the cities are &ldquo;shifting,&rdquo; or changing shape. </p>","parenttemplatename":"OSP-008-WIC","parenttemplateid":"","templateclusterid":"cc0f5905-c9cb-4eb5-9322-da8f0e0094cb","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959313,"updateDate":1691007959313}$SATQ$::jsonb, 1691007959313, 1691007959313),
    ($SATQ$9cdcd902$SATQ$, $SATQ$11f4885e-30a0-4023-b7fd-2b30f8d9c2f8$SATQ$::uuid, $SATQ$58a4f2d5-918a-43a1-89bb-d0712c5c2d27$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Charles &ldquo;Teenie&rdquo; Harris was a photographer for the <em>Pittsburgh Courier</em> from 1936 to 1975. During his career he took over 70,000 photographs documenting everyday life in Pittsburgh&rsquo;s Black communities. The Carnegie Museum of Art maintains thousands of his photographs, carefully <span aria-hidden="true">______</span><span class="sr-only">blank</span> them so that audiences can continue to view them well into the future.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"86d3677c-4d45-4457-a60a-829cb6d600e7","content":"<p>replacing</p>"},{"id":"09d02b27-fe9b-4a18-ad4b-9aa6b099134b","content":"<p>inventing</p>"},{"id":"45053557-e946-4ccf-853a-f6eefa9be379","content":"<p>preserving</p>"},{"id":"a420e07f-5b70-4eb5-85c3-88cbae98b354","content":"<p>counting</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["45053557-e946-4ccf-853a-f6eefa9be379"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. "Preserving" means "maintaining" or "keeping in good condition," so preserving the photographs means that audiences should be able to view them for a long time.</p><p>Choice A is incorrect. "Replacing" means "putting something new in place of" the photographs. Replacing the photos will make it so that audiences can&rsquo;t view them at all. Choice B is incorrect. "Inventing" means "creating a new idea, process, or thing." The museum can&rsquo;t invent photographs that already exist. Choice D is incorrect. Counting the photographs will not help audiences view them well into the future.</p>$SATQ$, false, 0, $SATQ$OSP-KA-WIC-E007$SATQ$, $SATQ$$SATQ$, $SATQ$542cc8d8-2882-4224-9d02-dedc740d5f3b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9cdcd902","external_id":"11f4885e-30a0-4023-b7fd-2b30f8d9c2f8","vaultid":"58a4f2d5-918a-43a1-89bb-d0712c5c2d27","uId":"14f079d6-7ceb-4467-8171-28ae67796a72","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Charles &ldquo;Teenie&rdquo; Harris was a photographer for the <em>Pittsburgh Courier</em> from 1936 to 1975. During his career he took over 70,000 photographs documenting everyday life in Pittsburgh&rsquo;s Black communities. The Carnegie Museum of Art maintains thousands of his photographs, carefully <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> them so that audiences can continue to view them well into the future.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"86d3677c-4d45-4457-a60a-829cb6d600e7","content":"<p>replacing</p>"},{"id":"09d02b27-fe9b-4a18-ad4b-9aa6b099134b","content":"<p>inventing</p>"},{"id":"45053557-e946-4ccf-853a-f6eefa9be379","content":"<p>preserving</p>"},{"id":"a420e07f-5b70-4eb5-85c3-88cbae98b354","content":"<p>counting</p>"}],"keys":["45053557-e946-4ccf-853a-f6eefa9be379"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. \"Preserving\" means \"maintaining\" or \"keeping in good condition,\" so preserving the photographs means that audiences should be able to view them for a long time.</p><p>Choice A is incorrect. \"Replacing\" means \"putting something new in place of\" the photographs. Replacing the photos will make it so that audiences can&rsquo;t view them at all. Choice B is incorrect. \"Inventing\" means \"creating a new idea, process, or thing.\" The museum can&rsquo;t invent photographs that already exist. Choice D is incorrect. Counting the photographs will not help audiences view them well into the future.</p>","parenttemplatename":"OSP-KA-WIC-E007","parenttemplateid":"","templateclusterid":"542cc8d8-2882-4224-9d02-dedc740d5f3b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959377,"updateDate":1691007959377}$SATQ$::jsonb, 1691007959377, 1691007959377),
    ($SATQ$9d73c9eb$SATQ$, $SATQ$359d3222-87e8-42c3-9002-6cfe68cb2f58$SATQ$::uuid, $SATQ$013f33af-395a-4c05-b136-448789dac990$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Osage Nation citizen Randy Tinker-Smith produced and directed the ballet <em>Wahzhazhe</em>, which vividly chronicles Osage history and culture. Telling Osage stories through ballet is <span aria-hidden="true">______</span><span class="sr-only">blank</span> choice because two of the foremost ballet dancers of the twentieth century were Osage: sisters Maria and Marjorie Tallchief.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"1e9a2474-c605-4cbe-912a-c75e35235b27","content":"<p>a suitable</p>"},{"id":"c4d6d3da-6890-47f1-9e0e-3898dfe1f44c","content":"<p>a determined</p>"},{"id":"ce0c73f9-8abd-45cf-b4f0-766de871103d","content":"<p>an arbitrary</p>"},{"id":"35282fe8-9dbd-445a-868d-d46083d2d4d5","content":"<p>an unpredictable</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["1e9a2474-c605-4cbe-912a-c75e35235b27"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. &ldquo;Suitable&rdquo; means &ldquo;appropriate for a particular purpose.&rdquo; Since the text indicates that two of the best ballet dancers of the twentieth century were Osage, we can infer that the author believes that ballet is a very suitable artform for telling Osage stories. </p><p>Choice B is incorrect. The text never suggests that Tinker-Smith&rsquo;s choice was determined. That would imply that Tinker-Smith initially faced some kind of obstacle or opposition, and nothing like that is mentioned in the passage. Choice C is incorrect. The text implies the opposite of this. &ldquo;Arbitrary&rdquo; means &ldquo;based on random choice or whim rather than reason.&rdquo; But the text does give us a good reason behind the choice to tell Osage stories through ballet: two of the best ballet dancers of the twentieth century were Osage. Choice D is incorrect. The text never suggests that Tinker-Smith&rsquo;s choice was &ldquo;unpredictable.&rdquo; Rather, the fact that two of the best ballet dancers of the twentieth century were Osage makes ballet especially appropriate for telling Osage stories. </p>$SATQ$, false, 0, $SATQ$OSP-KA-WIC-M002$SATQ$, $SATQ$$SATQ$, $SATQ$735a15a5-bb67-4be0-baf5-182bd219af00$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9d73c9eb","external_id":"359d3222-87e8-42c3-9002-6cfe68cb2f58","vaultid":"013f33af-395a-4c05-b136-448789dac990","uId":"821063e3-afbe-4d56-b8ce-81399342437d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Osage Nation citizen Randy Tinker-Smith produced and directed the ballet <em>Wahzhazhe</em>, which vividly chronicles Osage history and culture. Telling Osage stories through ballet is <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> choice because two of the foremost ballet dancers of the twentieth century were Osage: sisters Maria and Marjorie Tallchief.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"1e9a2474-c605-4cbe-912a-c75e35235b27","content":"<p>a suitable</p>"},{"id":"c4d6d3da-6890-47f1-9e0e-3898dfe1f44c","content":"<p>a determined</p>"},{"id":"ce0c73f9-8abd-45cf-b4f0-766de871103d","content":"<p>an arbitrary</p>"},{"id":"35282fe8-9dbd-445a-868d-d46083d2d4d5","content":"<p>an unpredictable</p>"}],"keys":["1e9a2474-c605-4cbe-912a-c75e35235b27"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. &ldquo;Suitable&rdquo; means &ldquo;appropriate for a particular purpose.&rdquo; Since the text indicates that two of the best ballet dancers of the twentieth century were Osage, we can infer that the author believes that ballet is a very suitable artform for telling Osage stories. </p><p>Choice B is incorrect. The text never suggests that Tinker-Smith&rsquo;s choice was determined. That would imply that Tinker-Smith initially faced some kind of obstacle or opposition, and nothing like that is mentioned in the passage. Choice C is incorrect. The text implies the opposite of this. &ldquo;Arbitrary&rdquo; means &ldquo;based on random choice or whim rather than reason.&rdquo; But the text does give us a good reason behind the choice to tell Osage stories through ballet: two of the best ballet dancers of the twentieth century were Osage. Choice D is incorrect. The text never suggests that Tinker-Smith&rsquo;s choice was &ldquo;unpredictable.&rdquo; Rather, the fact that two of the best ballet dancers of the twentieth century were Osage makes ballet especially appropriate for telling Osage stories. </p>","parenttemplatename":"OSP-KA-WIC-M002","parenttemplateid":"","templateclusterid":"735a15a5-bb67-4be0-baf5-182bd219af00","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959378,"updateDate":1691007959378}$SATQ$::jsonb, 1691007959378, 1691007959378),
    ($SATQ$9e501aaf$SATQ$, $SATQ$148dfa4e-795c-4cdf-a773-08cd072b8dd0$SATQ$::uuid, $SATQ$1a4212ef-51c1-4d88-bc10-07033b990ce8$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Research conducted by planetary scientist Katarina Miljkovic suggests that the Moon&rsquo;s surface may not accurately <span aria-hidden="true">______</span><span class="sr-only">blank</span> early impact events. When the Moon was still forming, its surface was softer, and asteroid or meteoroid impacts would have left less of an impression; thus, evidence of early impacts may no longer be present.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"11c70311-3137-4ee9-b225-4cee97525d95","content":"<p>reflect</p>"},{"id":"44ddfa03-94a5-4c93-88e7-5735b720d92a","content":"<p>receive</p>"},{"id":"f07a6d82-1534-4d49-81db-dbfbb6b39a70","content":"<p>evaluate</p>"},{"id":"65bddcc5-73d2-4e2b-895a-b60b788fc8f0","content":"<p>mimic</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["11c70311-3137-4ee9-b225-4cee97525d95"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the Moon&rsquo;s surface. In this context, &ldquo;reflect&rdquo; means show or make apparent. The text states that because the surface of the Moon was softer when the Moon was still forming than it is now, early asteroid and meteoroid impacts &ldquo;would have left less of an impression&rdquo; and, as a result, evidence of them may no longer exist. This context supports the idea that the surface of the Moon may not accurately show signs of early impact events. </p><p>Choice B is incorrect because it wouldn&rsquo;t make sense to say that the surface of the Moon may not accurately &ldquo;receive,&rdquo; or acquire or experience, early impacts from asteroids or meteoroids. The text indicates that the impacts have already occurred, and it isn&rsquo;t clear how the Moon&rsquo;s surface could be accurate or inaccurate in experiencing them. Choice C is incorrect because it wouldn&rsquo;t make sense to say that the surface of the Moon may not accurately &ldquo;evaluate,&rdquo; or determine the significance or condition of, early impacts from asteroids or meteoroids, since that would suggest that it&rsquo;s possible for the Moon&rsquo;s surface to make a decision of any kind.&nbsp;Choice D is incorrect. In this context, &ldquo;mimic&rdquo; would mean to deliberately simulate or closely imitate something. It wouldn&rsquo;t make sense to say that the surface of the Moon may not accurately mimic early asteroid and meteoroid impacts, since that would suggest that it&rsquo;s possible for the Moon to deliberately imitate something.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-963-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$acb111e6-e1ec-4687-b140-012db500958e$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"9e501aaf","external_id":"148dfa4e-795c-4cdf-a773-08cd072b8dd0","vaultid":"1a4212ef-51c1-4d88-bc10-07033b990ce8","uId":"14bb8da8-2652-482b-b774-3b7140db0c56","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Research conducted by planetary scientist Katarina Miljkovic suggests that the Moon&rsquo;s surface may not accurately <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> early impact events. When the Moon was still forming, its surface was softer, and asteroid or meteoroid impacts would have left less of an impression; thus, evidence of early impacts may no longer be present.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"11c70311-3137-4ee9-b225-4cee97525d95","content":"<p>reflect</p>"},{"id":"44ddfa03-94a5-4c93-88e7-5735b720d92a","content":"<p>receive</p>"},{"id":"f07a6d82-1534-4d49-81db-dbfbb6b39a70","content":"<p>evaluate</p>"},{"id":"65bddcc5-73d2-4e2b-895a-b60b788fc8f0","content":"<p>mimic</p>"}],"keys":["11c70311-3137-4ee9-b225-4cee97525d95"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the Moon&rsquo;s surface. In this context, &ldquo;reflect&rdquo; means show or make apparent. The text states that because the surface of the Moon was softer when the Moon was still forming than it is now, early asteroid and meteoroid impacts &ldquo;would have left less of an impression&rdquo; and, as a result, evidence of them may no longer exist. This context supports the idea that the surface of the Moon may not accurately show signs of early impact events. </p><p>Choice B is incorrect because it wouldn&rsquo;t make sense to say that the surface of the Moon may not accurately &ldquo;receive,&rdquo; or acquire or experience, early impacts from asteroids or meteoroids. The text indicates that the impacts have already occurred, and it isn&rsquo;t clear how the Moon&rsquo;s surface could be accurate or inaccurate in experiencing them. Choice C is incorrect because it wouldn&rsquo;t make sense to say that the surface of the Moon may not accurately &ldquo;evaluate,&rdquo; or determine the significance or condition of, early impacts from asteroids or meteoroids, since that would suggest that it&rsquo;s possible for the Moon&rsquo;s surface to make a decision of any kind.&nbsp;Choice D is incorrect. In this context, &ldquo;mimic&rdquo; would mean to deliberately simulate or closely imitate something. It wouldn&rsquo;t make sense to say that the surface of the Moon may not accurately mimic early asteroid and meteoroid impacts, since that would suggest that it&rsquo;s possible for the Moon to deliberately imitate something.&nbsp;</p>","parenttemplatename":"OSP-963-WIC","parenttemplateid":"","templateclusterid":"acb111e6-e1ec-4687-b140-012db500958e","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959357,"updateDate":1691007959357}$SATQ$::jsonb, 1691007959357, 1691007959357),
    ($SATQ$a06c434d$SATQ$, $SATQ$94dcf619-8c65-49bb-af1e-f8bc0e5c3760$SATQ$::uuid, $SATQ$002eac6f-8ec8-461e-9698-29d07f99ce19$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The work of Kiowa painter T.C. Cannon derives its power in part from the tension among his <span aria-hidden="true">______</span><span class="sr-only">blank</span> influences: classic European portraiture, with its realistic treatment of faces; the American pop art movement, with its vivid colors; and flatstyle, the intertribal painting style that rejects the effect of depth typically achieved through shading and perspective.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"b04e05f1-04da-429b-9663-88f5c248a775","content":"<p>complementary</p>"},{"id":"b8cd6fb8-a92a-4f48-b728-904b30939a8a","content":"<p>unknown</p>"},{"id":"2fd0bc70-d43a-47b8-9c3d-2dbf0deee567","content":"<p>disparate</p>"},{"id":"7c463b3e-2209-46a3-a99f-49dcc0cc8133","content":"<p>interchangeable</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["2fd0bc70-d43a-47b8-9c3d-2dbf0deee567"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the artistic styles that have influenced Cannon&rsquo;s work. As used in this context, &ldquo;disparate&rdquo; means distinct or dissimilar. The text indicates that a tension exists among the styles that have influenced Cannon&rsquo;s work and goes on to describe how those styles differ: classic European portraiture favors realism, American pop art uses vivid colors, and intertribal flatstyle rejects the use of shading and perspective to achieve depth. This context suggests that the styles that have influenced Cannon&rsquo;s work are disparate.&nbsp;</p><p>Choice A is incorrect because the text indicates that there is a tension among the influences on Cannon&rsquo;s artwork, so it wouldn&rsquo;t make sense to say that the influences are &ldquo;complementary,&rdquo; or that they complete one another or make up for one another&rsquo;s deficiencies. Choice B is incorrect because it wouldn&rsquo;t make sense to characterize Cannon&rsquo;s influences as &ldquo;unknown,&rdquo; or not familiar; it&rsquo;s clear that the influences are known because the text goes on to list them. Choice D is incorrect because the text indicates that there is a tension among the influences on Cannon&rsquo;s work, not that they are&nbsp; &ldquo;interchangeable,&rdquo; or capable of being used in one another&rsquo;s place. </p>$SATQ$, false, 0, $SATQ$OSP-940-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$f1d5dbc2-7e97-4d27-afdc-8bea560851c2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a06c434d","external_id":"94dcf619-8c65-49bb-af1e-f8bc0e5c3760","vaultid":"002eac6f-8ec8-461e-9698-29d07f99ce19","uId":"70f7aaa6-3719-4959-9858-9c39b156e642","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The work of Kiowa painter T.C. Cannon derives its power in part from the tension among his <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> influences: classic European portraiture, with its realistic treatment of faces; the American pop art movement, with its vivid colors; and flatstyle, the intertribal painting style that rejects the effect of depth typically achieved through shading and perspective.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"b04e05f1-04da-429b-9663-88f5c248a775","content":"<p>complementary</p>"},{"id":"b8cd6fb8-a92a-4f48-b728-904b30939a8a","content":"<p>unknown</p>"},{"id":"2fd0bc70-d43a-47b8-9c3d-2dbf0deee567","content":"<p>disparate</p>"},{"id":"7c463b3e-2209-46a3-a99f-49dcc0cc8133","content":"<p>interchangeable</p>"}],"keys":["2fd0bc70-d43a-47b8-9c3d-2dbf0deee567"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the artistic styles that have influenced Cannon&rsquo;s work. As used in this context, &ldquo;disparate&rdquo; means distinct or dissimilar. The text indicates that a tension exists among the styles that have influenced Cannon&rsquo;s work and goes on to describe how those styles differ: classic European portraiture favors realism, American pop art uses vivid colors, and intertribal flatstyle rejects the use of shading and perspective to achieve depth. This context suggests that the styles that have influenced Cannon&rsquo;s work are disparate.&nbsp;</p><p>Choice A is incorrect because the text indicates that there is a tension among the influences on Cannon&rsquo;s artwork, so it wouldn&rsquo;t make sense to say that the influences are &ldquo;complementary,&rdquo; or that they complete one another or make up for one another&rsquo;s deficiencies. Choice B is incorrect because it wouldn&rsquo;t make sense to characterize Cannon&rsquo;s influences as &ldquo;unknown,&rdquo; or not familiar; it&rsquo;s clear that the influences are known because the text goes on to list them. Choice D is incorrect because the text indicates that there is a tension among the influences on Cannon&rsquo;s work, not that they are&nbsp; &ldquo;interchangeable,&rdquo; or capable of being used in one another&rsquo;s place. </p>","parenttemplatename":"OSP-940-WIC","parenttemplateid":"","templateclusterid":"f1d5dbc2-7e97-4d27-afdc-8bea560851c2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959356,"updateDate":1691007959356}$SATQ$::jsonb, 1691007959356, 1691007959356)
